import logging
import signal
import sys
import time
from enum import Enum
from typing import Optional, List, Tuple
import smbus2
import threading

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ADCMode(Enum):
    SINGLE_ENDED = 1
    DIFFERENTIAL = 2
    COMPARATOR = 3

class ADS1015:
    I2C_ADDRESS = 0x48
    REG_CONFIG = 0x01
    REG_RESULT = 0x00

    # Configuration register bits
    # Bit 15: 1 = MSB first, 0 = LSB first (default)
    # Bit 14: 1 = 16-bit mode, 0 = 12-bit mode (default)
    # Bit 13: 1 = Comparator enabled, 0 = disabled
    # Bit 12: 1 = Comparator non-inverting input, 0 = inverting input
    # Bit 11: 1 = Comparator latch, 0 = no latch
    # Bit 10: 1 = Comparator traditional mode, 0 = non-traditional
    # Bit 9: 1 = Comparator active low, 0 = active high
    # Bit 8: 1 = Comparator queue, 0 = no queue
    # Bit 7: 1 = Comparator interrupt, 0 = no interrupt
    # Bit 6: 1 = Comparator high threshold, 0 = low threshold
    # Bit 5: 1 = Comparator high threshold, 0 = low threshold
    # Bit 4: 1 = Comparator high threshold, 0 = low threshold
    # Bit 3: 1 = Comparator high threshold, 0 = low threshold
    # Bit 2: 1 = Comparator high threshold, 0 = low threshold
    # Bit 1: 1 = Comparator high threshold, 0 = low threshold
    # Bit 0: 1 = Comparator high threshold, 0 = low threshold

    # Configuration register values
    # PGA: 6144, 4096, 2048, 1024, 512, 256, 128, 64
    # SPS: 128, 250, 490, 975, 1950, 3900, 7800, 15600
    # Channel: 0-3
    # Mode: 0 = single-ended, 1 = differential

    def __init__(self, address: int = I2C_ADDRESS, busnum: int = 1, debug: bool = False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.bus = None
        self.last_results = []
        self.lock = threading.Lock()
        self.running = False
        self.signal_received = False

        # Register configuration
        self.config = 0x8583  # Default configuration: 12-bit mode, 250 SPS, single-ended, channel 0

        # Set up signal handling
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def signal_handler(self, sig, frame):
        self.signal_received = True
        self.stop_continuous_conversion()
        self.close_i2c()
        sys.exit(0)

    def close_i2c(self):
        if self.bus:
            try:
                self.bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None

    def _i2c_read(self, reg):
        try:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            return self.bus.read_byte_data(self.address, reg)
        except Exception as e:
            logging.error(f"I2C read error: {e}")
            return -1

    def _i2c_write(self, reg, value):
        try:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            self.bus.write_byte_data(self.address, reg, value)
        except Exception as e:
            logging.error(f"I2C write error: {e}")

    def _configure(self):
        try:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            self._i2c_write(self.REG_CONFIG, self.config)
        except Exception as e:
            logging.error(f"ADC configuration error: {e}")

    def _read_adc(self):
        try:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            result = self._i2c_read(self.REG_RESULT)
            return result
        except Exception as e:
            logging.error(f"ADC read error: {e}")
            return -1

    def _set_config(self, channel: int, pga: int, sps: int, mode: int):
        # Set channel
        if channel < 0 or channel > 3:
            raise ValueError("Channel must be between 0 and 3")
        channel_config = (channel << 4) & 0x30

        # Set PGA
        pga_config = 0
        if pga == 6144:
            pga_config = 0x00
        elif pga == 4096:
            pga_config = 0x01
        elif pga == 2048:
            pga_config = 0x02
        elif pga == 1024:
            pga_config = 0x03
        elif pga == 512:
            pga_config = 0x04
        elif pga == 256:
            pga_config = 0x05
        elif pga == 128:
            pga_config = 0x06
        elif pga == 64:
            pga_config = 0x07
        else:
            raise ValueError(f"Invalid PGA value: {pga}")

        # Set SPS
        sps_config = 0
        if sps == 128:
            sps_config = 0x00
        elif sps == 250:
            sps_config = 0x01
        elif sps == 490:
            sps_config = 0x02
        elif sps == 975:
            sps_config = 0x03
        elif sps == 1950:
            sps_config = 0x04
        elif sps == 3900:
            sps_config = 0x05
        elif sps == 7800:
            sps_config = 0x06
        elif sps == 15600:
            sps_config = 0x07
        else:
            raise ValueError(f"Invalid SPS value: {sps}")

        # Set mode
        mode_config = mode & 0x01

        # Build configuration
        self.config = (mode_config << 13) | (channel_config << 12) | (pga_config << 9) | (sps_config << 6)

    def _start_continuous_conversion(self, channel: int, pga: int, sps: int):
        try:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            self._set_config(channel, pga, sps, ADCMode.SINGLE_ENDED.value)
            self._i2c_write(self.REG_CONFIG, self.config)
            self.running = True
        except Exception as e:
            logging.error(f"Error starting continuous conversion: {e}")
            self.running = False

    def _stop_continuous_conversion(self):
        try:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            self._i2c_write(self.REG_CONFIG, 0x8583)
            self.running = False
        except Exception as e:
            logging.error(f"Error stopping continuous conversion: {e}")
            self.running = False

    def read_adc_single_ended(self, channel: int = 0, pga: int = 6144, sps: int = 250) -> int:
        try:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            self._set_config(channel, pga, sps, ADCMode.SINGLE_ENDED.value)
            self._i2c_write(self.REG_CONFIG, self.config)
            time.sleep(0.001)  # Wait for conversion to complete
            result = self._read_adc()
            if result == -1:
                return -1
            return result
        except Exception as e:
            logging.error(f"Error reading ADC single-ended: {e}")
            return -1

    def start_continuous_conversion(self, channel: int = 0, pga: int = 6144, sps: int = 250):
        try:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            self._set_config(channel, pga, sps, ADCMode.SINGLE_ENDED.value)
            self._i2c_write(self.REG_CONFIG, self.config)
            self.running = True
        except Exception as e:
            logging.error(f"Error starting continuous conversion: {e}")
            self.running = False

    def get_last_conversion_results(self) -> List[int]:
        try:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            with self.lock:
                return self.last_results.copy()
        except Exception as e:
            logging.error(f"Error getting last conversion results: {e}")
            return []

    def start_single_ended_comparator(self, channel: int = 0, threshold_high: int = 2047, threshold_low: int = 0, pga: int = 6144, sps: int = 250, active_low: bool = True, traditional_mode: bool = True, latching: bool = False, num_readings: int = 1):
        try:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            self._set_config(channel, pga, sps, ADCMode.COMPARATOR.value)
            self._i2c_write(self.REG_CONFIG, self.config)

            # Set comparator configuration
            comparator_config = 0
            comparator_config |= (1 << 13)  # Comparator enabled
            comparator_config |= (1 << 12)  # Comparator non-inverting input
            comparator_config |= (1 << 11)  # Comparator latch
            comparator_config |= (1 << 10) if traditional_mode else 0  # Comparator traditional mode
            comparator_config |= (1 << 9) if active_low else 0  # Comparator active low
            comparator_config |= (1 << 8) if latching else 0  # Comparator latch
            comparator_config |= (1 << 7)  # Comparator interrupt
            comparator_config |= (1 << 6)  # Comparator high threshold
            comparator_config |= (threshold_high >> 8) & 0x0F  # High threshold
            comparator_config |= (threshold_low >> 4) & 0x0F  # Low threshold

            self._i2c_write(self.REG_CONFIG, comparator_config)
            self.running = True
        except Exception as e:
            logging.error(f"Error starting single-ended comparator: {e}")
            self.running = False

    def close(self):
        self.signal_received = True
        self.stop_continuous_conversion()
        self.close_i2c()

    def __del__(self):
        self.close()

if __name__ == "__main__":
    try:
        adc = ADS1015(address=0x48, busnum=1, debug=True)
        adc.bus = smbus2.SMBus(adc.busnum)
        adc._configure()

        # Example usage
        print("Reading ADC single-ended...")
        result = adc.read_adc_single_ended(channel=0, pga=6144, sps=250)
        print(f"ADC single-ended result: {result}")

        print("Starting continuous conversion...")
        adc.start_continuous_conversion(channel=0, pga=6144, sps=250)
        time.sleep(2)
        print("Last conversion results:")
        for result in adc.get_last_conversion_results():
            print(result)

        print("Starting single-ended comparator...")
        adc.start_single_ended_comparator(channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1)
        time.sleep(2)
        print("Comparator results:")
        for result in adc.get_last_conversion_results():
            print(result)

    except Exception as e:
        logging.error(f"Main program error: {e}")
    finally:
        adc.close()

