import logging
import time
import spidev
import RPi.GPIO as GPIO
from threading import Thread
import signal
import sys

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SmartGardenController:
    def __init__(self):
        self.spi = None
        self.pump_pin = 18
        self.dry_threshold = 450
        self.setup_gpio()
        self.setup_spi()

    def setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pump_pin, GPIO.OUT)
        except Exception as e:
            logging.error(f"GPIO setup failed: {e}")
            raise

    def setup_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)  # bus 0, device 0 (CE0)
            self.spi.max_speed_hz = 1350000  # 1.35 MHz
            self.spi.mode = 0b00  # CPOL=0, CPHA=0
            self.spi.bits_per_word = 8
        except Exception as e:
            logging.error(f"SPI setup failed: {e}")
            raise

    def read_moisture(self):
        try:
            # MCP3008 command format: 0b00110000 (for CH0, 10-bit, single-ended)
            # 8-bit command + 12-bit data (MSB first)
            # We read 3 bytes: 1st byte is command, 2nd and 3rd are data
            # Convert to 10-bit value
            cmd = 0b00110000
            response = self.spi.xfer2([cmd, 0, 0])
            adc_value = ((response[1] << 8) | response[2]) >> 2
            return adc_value
        except Exception as e:
            logging.error(f"SPI transaction failed: {e}")
            return -1

    def run_pump(self, seconds):
        try:
            GPIO.output(self.pump_pin, GPIO.HIGH)
            time.sleep(seconds)
            GPIO.output(self.pump_pin, GPIO.LOW)
        except Exception as e:
            logging.error(f"Failed to run pump: {e}")
            raise

    def irrigation_cycle(self):
        moisture = self.read_moisture()
        if moisture == -1:
            return False
        if moisture > self.dry_threshold:
            self.run_pump(2)
            return True
        return False

    def close(self):
        try:
            if self.spi:
                self.spi.close()
            GPIO.cleanup()
        except Exception as e:
            logging.error(f"Error during cleanup: {e}")

def schedule_cycles(controller, cycle_count, interval_seconds):
    for _ in range(cycle_count):
        try:
            if controller.irrigation_cycle():
                logging.info("Irrigation cycle triggered.")
            else:
                logging.info("Irrigation cycle not triggered.")
            time.sleep(interval_seconds)
        except Exception as e:
            logging.error(f"Error during scheduled cycle: {e}")

def signal_handler(sig, frame):
    logging.info("Received shutdown signal. Cleaning up...")
    controller.close()
    sys.exit(0)

if __name__ == "__main__":
    controller = None
    try:
        controller = SmartGardenController()
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)
        schedule_cycles(controller, 10, 3)
    except Exception as e:
        logging.error(f"Main program error: {e}")
    finally:
        if controller:
            controller.close()

