import sys
import time
import logging
import threading
from queue import Queue
import argparse
from gpiozero import DigitalInputDevice
from spidev import SpiDev
import paho.mqtt.client as mqtt

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = False
        self.spi = None
        self.digital_inputs = []

        if sensor_type == 'digital':
            for pin in gpio_pins:
                self.digital_inputs.append(DigitalInputDevice(pin, pull_up=True, active_state=True))
        elif sensor_type == 'analog':
            self.spi = SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = spi_speed
        else:
            raise ValueError("Invalid sensor type. Use 'digital' or 'analog'.")

    def _read_analog(self, channel):
        if not self.spi:
            raise RuntimeError("SPI not initialized for analog sensor.")
        # SPI command: start bit (1), single-ended mode (0), channel bits (3), dummy byte (0)
        command = 0b10000000 | (channel << 4) | 0
        self.spi.xfer2([command, 0])
        data = self.spi.xfer2([0, 0])
        # Extract 10-bit result
        result = (data[0] & 0x0F) << 8 | data[1] & 0xF0
        return result >> 4  # 10-bit result

    def _debounce(self):
        time.sleep(0.1)

    def _detect_event(self):
        if self.sensor_type == 'digital':
            for pin in self.digital_inputs:
                if pin.value:
                    return True
        elif self.sensor_type == 'analog':
            reading = self._read_analog(self.channels[self.sensor_id])
            if reading >= self.threshold:
                return True
        return False

    def run(self):
        self.running = True
        try:
            while self.running:
                if self._detect_event():
                    message = f"Sensor {self.sensor_id} event detected"
                    if self.log_queue:
                        self.log_queue.put(message)
                time.sleep(1.0 / self.sample_rate)
                self._debounce()
        except Exception as e:
            logging.error(f"Error in sensor {self.sensor_id}: {str(e)}")
        finally:
            self.stop()

    def stop(self):
        self.running = False
        if self.sensor_type == 'analog':
            self.spi.close()

    def __del__(self):
        self.stop()

def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitor")
    parser.add_argument('--sensor_type', required=True, choices=['digital', 'analog'], help="Type of sensor: digital or analog")
    parser.add_argument('--threshold', type=int, default=512, help="Analog threshold for event detection")
    parser.add_argument('--sample_rate', type=int, default=10, help="Sample rate in Hz")
    parser.add_argument('--log_file', default='sound_sensor.log', help="Log file path")
    parser.add_argument('--gpio_pins', nargs='+', type=int, help="BCM GPIO pins for digital sensors")
    parser.add_argument('--channels', nargs='+', type=int, help="Channels for analog sensors")
    parser.add_argument('--spi_speed', type=int, default=1000000, help="SPI speed in Hz")
    parser.add_argument('--sensor_ids', nargs='+', type=int, required=True, help="Sensor IDs")

    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    log_queue = Queue()

    sensors = []
    for sensor_id in args.sensor_ids:
        if args.sensor_type == 'digital':
            if not args.gpio_pins or len(args.gpio_pins) < len(args.sensor_ids):
                raise ValueError("Not enough GPIO pins provided for digital sensors.")
            sensors.append(SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate,
                                       args.gpio_pins, args.channels, args.spi_speed, log_queue))
        elif args.sensor_type == 'analog':
            if not args.channels or len(args.channels) < len(args.sensor_ids):
                raise ValueError("Not enough channels provided for analog sensors.")
            sensors.append(SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate,
                                       args.gpio_pins, args.channels, args.spi_speed, log_queue))

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run, daemon=True)
        thread.start()
        threads.append(thread)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Shutting down gracefully...")
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join()
        logging.info("Shutdown complete.")

if __name__ == "__main__":
    main()

