    print(f"Error initializing ADS1115: {e}")
    sys.exit(1)

# Configure ADS1115
ads.gain = 1  # ±4.096V range

def read_adc():
    try:
        # Read all four channels
        values = [ads.read_adc(i, gain=ads.gain) for i in range(4)]
        return values
    except (RuntimeError, OSError) as e:
        print(f"I2C error reading ADC: {e}")
        return None

def print_table(values):
    print("Channel | Raw Value")
    print("--------|----------")
    for i, val in enumerate(values):
        print(f"   {i}    |   {val:6d}")

def main():
    try:
        while True:
            values = read_adc()
            if values is not None:
                print_table(values)
            time.sleep(0.5)
