        self.spi = spidev.SpiDev()
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.cs_pin = cs_pin
        self._setup_spi()

    def _setup_spi(self):
        try:
            self.spi.open(self.spi_bus, self.spi_device)
            self.spi.max_speed_hz = 1000000  # 1 MHz
            self.spi.mode = 0b00  # CPOL=0, CPHA=0
        except OSError as e:
            print(f"SPI setup failed: {e}")
            sys.exit(1)

    def _read_adc(self, channel):
        try:
            # Construct 8-bit command: 0b11100000 + channel number
            command = 0b11100000 | channel
            # Read 3 bytes (first byte is dummy, next two are data)
            data = self.spi.xfer2([command, 0x00, 0x00])
            # Extract the 10-bit value
            adc_value = (data[1] << 8) | data[2]
            return adc_value
        except OSError as e:
            print(f"SPI read error: {e}")
            return None

    def read_raw(self):
        return self._read_adc(0)

