import json
import time
import signal
import logging
import os
import sys
import threading
from gpiozero import DistanceSensor
from datetime import datetime
from enum import Enum
from typing import Optional, List, Dict, Any

# Configuration defaults
DEFAULT_CONFIG = {
    "offset": 0.0,
    "max_distance": 200.0,
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log"
}

# Sensor configuration
SENSOR_CONFIG = {
    "sensor1": {
        "trigger": 17,
        "echo": 18
    },
    "sensor2": {
        "trigger": 22,
        "echo": 23
    },
    "sensor3": {
        "trigger": 24,
        "echo": 25
    }
}

# Enum for sensor status
class SensorStatus(Enum):
    OK = "OK"
    ERROR = "ERROR"
    EXCLUDED = "EXCLUDED"

# Initialize logging
logging.basicConfig(
    filename='water_level.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global state
sensor_status = {sensor: SensorStatus.OK for sensor in SENSOR_CONFIG}
valid_readings = {sensor: [] for sensor in SENSOR_CONFIG}
last_alert_time = 0
alert_cooldown = 0
config = DEFAULT_CONFIG.copy()

def load_config(config_file: str = "config.json") -> Dict[str, Any]:
    """Load configuration from file, with fallback to defaults."""
    if not os.path.exists(config_file):
        logging.warning(f"Config file {config_file} not found, using defaults.")
        return DEFAULT_CONFIG.copy()
    try:
        with open(config_file, "r") as f:
            config_data = json.load(f)
        # Merge with defaults
        for key in DEFAULT_CONFIG:
            if key not in config_data:
                config_data[key] = DEFAULT_CONFIG[key]
        return config_data
    except Exception as e:
        logging.error(f"Error loading config file: {e}")
        return DEFAULT_CONFIG.copy()

def setup_gpio() -> bool:
    """Initialize GPIO with sensors, return True on success."""
    try:
        # Initialize sensors
        sensors = {}
        for sensor_name, pins in SENSOR_CONFIG.items():
            trigger_pin = pins["trigger"]
            echo_pin = pins["echo"]
            sensors[sensor_name] = DistanceSensor(trigger=trigger_pin, echo=echo_pin, threshold_distance=0.5)
        return sensors
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return None

def get_distance(sensor: DistanceSensor) -> Optional[float]:
    """Get distance from sensor, return None on timeout."""
    try:
        distance = sensor.distance
        if distance is None:
            return None
        return distance
    except Exception as e:
        logging.error(f"Error reading distance from sensor: {e}")
        return None

def get_median_distance() -> float:
    """Compute median of valid readings, excluding sensors with errors."""
    valid_distances = []
    for sensor_name in SENSOR_CONFIG:
        if sensor_status[sensor_name] == SensorStatus.OK:
            if len(valid_readings[sensor_name]) >= 3:
                valid_distances.append(valid_readings[sensor_name][-3:])
    if not valid_distances:
        return None
    # Flatten and sort
    flat_distances = [d for distances in valid_distances for d in distances]
    flat_distances.sort()
    return flat_distances[len(flat_distances) // 2]

def check_thresholds(median_distance: float) -> bool:
    """Check if median distance is within thresholds."""
    if median_distance is None:
        return False
    adjusted_distance = median_distance + config["offset"]
    if adjusted_distance < config["alert_threshold_low"] or adjusted_distance > config["alert_threshold_high"]:
        return True
    return False

def log_water_level(median_distance: float) -> None:
    """Log water level to file."""
    try:
        with open(config["log_file"], "a") as f:
            f.write(f"{datetime.now()} - {median_distance:.2f} cm\n")
    except Exception as e:
        logging.error(f"Error writing to log file: {e}")

def check_alerts(median_distance: float) -> None:
    """Check if alert conditions are met and trigger alerts."""
    global last_alert_time, alert_cooldown
    if not check_thresholds(median_distance):
        return
    current_time = time.time()
    if current_time - last_alert_time < config["alert_repeat_delay"]:
        return
    last_alert_time = current_time
    alert_cooldown = 10  # 10 seconds cooldown after alert
    logging.warning(f"Water level alert: {median_distance:.2f} cm (adjusted: {median_distance + config['offset']:.2f} cm)")
    print(f"Water level alert: {median_distance:.2f} cm (adjusted: {median_distance + config['offset']:.2f} cm)")

def update_sensor_status(sensor_name: str, success: bool) -> None:
    """Update sensor status based on success of reading."""
    global valid_readings
    if success:
        sensor_status[sensor_name] = SensorStatus.OK
        valid_readings[sensor_name].append(get_distance(sensors[sensor_name]))
        if len(valid_readings[sensor_name]) > 5:
            valid_readings[sensor_name] = valid_readings[sensor_name][-5:]
    else:
        if sensor_status[sensor_name] == SensorStatus.OK:
            sensor_status[sensor_name] = SensorStatus.ERROR
        elif sensor_status[sensor_name] == SensorStatus.ERROR:
            if len(valid_readings[sensor_name]) >= 5:
                sensor_status[sensor_name] = SensorStatus.EXCLUDED
                logging.info(f"Excluding sensor {sensor_name} due to 5 consecutive errors.")

def poll_sensors() -> None:
    """Poll all sensors and update status."""
    global sensors
    for sensor_name in SENSOR_CONFIG:
        distance = get_distance(sensors[sensor_name])
        success = distance is not None
        update_sensor_status(sensor_name, success)

def main_loop() -> None:
    """Main loop to poll sensors and check thresholds."""
    global sensors, config, last_alert_time, alert_cooldown
    config = load_config()
    sensors = setup_gpio()
    if sensors is None:
        logging.error("Failed to initialize GPIO. Exiting.")
        sys.exit(0)
    try:
        while True:
            if alert_cooldown > 0:
                alert_cooldown -= 1
                time.sleep(1)
                continue
            poll_sensors()
            median_distance = get_median_distance()
            if median_distance is not None:
                log_water_level(median_distance)
                check_alerts(median_distance)
            time.sleep(5)
    except KeyboardInterrupt:
        logging.info("Received keyboard interrupt, shutting down.")
    finally:
        for sensor in sensors.values():
            sensor.close()
        logging.info("GPIO resources released.")

def signal_handler(sig, frame):
    """Handle shutdown signals."""
    logging.info("Shutting down gracefully...")
    for sensor in sensors.values():
        sensor.close()
    sys.exit(0)

if __name__ == "__main__":
    # Setup signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        main_loop()
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        sys.exit(0)

