import os
import time
import signal
import logging
import sys
from gpiozero import PWMOutputDevice
from contextlib import contextmanager

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Fan control parameters
FAN_PIN = 17  # BCM pin
PWM_THRESHOLDS = [65, 55, 50, 45]
PWM_VALUES = [1.0, 0.8, 0.6, 0.4]

# Validate thresholds and PWM values
if len(PWM_THRESHOLDS) != len(PWM_VALUES):
    raise ValueError("PWM thresholds and PWM values arrays must be of equal length")
for duty in PWM_VALUES:
    if not 0.0 <= duty <= 1.0:
        raise ValueError("All PWM values must be in the range 0.0 to 1.0")

# Default PWM value
DEFAULT_PWM = 1.0

@contextmanager
def fan_pwm():
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=1000)
        yield fan
    except Exception as e:
        logging.error(f"Failed to initialize PWM on pin {FAN_PIN}: {e}")
        sys.exit(1)

def read_cpu_temperature():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            temp = int(f.read()) / 1000.0
        return temp
    except Exception as e:
        logging.error(f"Error reading CPU temperature: {e}")
        return None

def get_pwm_duty(temp):
    if temp is None:
        return DEFAULT_PWM
    for i in range(len(PWM_THRESHOLDS) - 1, -1, -1):
        if temp > PWM_THRESHOLDS[i]:
            return PWM_VALUES[i]
    return PWM_VALUES[-1]

def signal_handler(sig, frame, fan):
    logging.info("Received shutdown signal. Resetting fan to default PWM.")
    try:
        fan.value = DEFAULT_PWM
    except Exception as e:
        logging.error(f"Error resetting fan PWM: {e}")
    finally:
        fan.close()
        sys.exit(0)

def main():
    logging.info("Starting fan control program.")
    with fan_pwm() as fan:
        fan.value = DEFAULT_PWM
        logging.info("Fan started at full speed (PWM 1.0).")

        try:
            signal.signal(signal.SIGINT, lambda sig, frame: signal_handler(sig, frame, fan))
            signal.signal(signal.SIGTERM, lambda sig, frame: signal_handler(sig, frame, fan))

            while True:
                temp = read_cpu_temperature()
                if temp is not None:
                    logging.info(f"Current temperature: {temp:.1f}°C")
                    target_pwm = get_pwm_duty(temp)
                    logging.info(f"Target PWM: {target_pwm:.1f}")
                else:
                    logging.info("Failed to read temperature, using default PWM.")
                    target_pwm = DEFAULT_PWM

                try:
                    fan.value = target_pwm
                except Exception as e:
                    logging.error(f"Error setting PWM duty cycle: {e}")

                time.sleep(5)
        except KeyboardInterrupt:
            logging.info("Shutting down fan control program.")
            signal_handler(signal.SIGINT, None, fan)

if __name__ == "__main__":
    main()

