def cleanup():
    for zone in pirs:
        if pirs[zone]:
            pirs[zone].close()
    if vl53:
        vl53.stop_ranging()
    if client:
        client.disconnect()
    logging.info("Atexit cleanup complete")

# Main loop
def main():
    global client
    client = connect_mqtt()
    client.loop_start()

    atexit.register(cleanup)
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    for zone in pirs:
        if pirs[zone]:
            pirs[zone].when_activated = lambda z=zone: handle_pir(z)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Main loop interrupted")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

