from gpiozero import Button, LED
from picamera2 import Picamera2, PreviewConfiguration
import signal
import sys

# Configuration
BUTTON_PIN = 17
CAMERA_PREVIEW_WIDTH = 640
CAMERA_PREVIEW_HEIGHT = 480
CAMERA_FORMAT = "XRGB8888"
IMAGE_DIR = "images"
DEBOUNCE_DELAY = 0.2
MAIN_LOOP_PAUSE = 0.1

# Initialize camera and GPIO
picam2 = None
button = None
led = None
camera_initialized = False

def setup_camera():
    global picam2, camera_initialized
    try:
        picam2 = Picamera2()
        config = PreviewConfiguration(size=(CAMERA_PREVIEW_WIDTH, CAMERA_PREVIEW_HEIGHT), format=CAMERA_FORMAT)
        picam2.configure(config)
        picam2.start()
        camera_initialized = True
        print("Camera initialized successfully.")
    except Exception as e:
        print(f"Failed to initialize camera: {e}")
        camera_initialized = False

def setup_gpio():
    global button, led
    try:
        button = Button(BUTTON_PIN, pull_up=True)
        led = LED(27)  # Optional LED for visual feedback
        print("GPIO setup completed.")
    except Exception as e:
        print(f"Failed to setup GPIO: {e}")

def create_image_directory():
    if not os.path.exists(IMAGE_DIR):
        try:
            os.makedirs(IMAGE_DIR)
            print(f"Created directory: {IMAGE_DIR}")
        except Exception as e:
            print(f"Failed to create directory: {e}")
            return False
    return True

def capture_image():
    global picam2
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    image_path = os.path.join(IMAGE_DIR, f"capture_{timestamp}.jpg")
    try:
        picam2.capture_file(image_path)
        print(f"Image saved to: {image_path}")
        return True
    except Exception as e:
        print(f"Failed to capture image: {e}")
        return False

def generate_sensor_data():
    temperature = round(random.uniform(10, 40), 1)
    humidity = round(random.uniform(30, 90), 1)
    return temperature, humidity

def handle_button_press():
    print("Button pressed - capturing image...")
    temperature, humidity = generate_sensor_data()
    print(f"Sensor Data: Temperature={temperature}°C, Humidity={humidity}%")
    if create_image_directory() and camera_initialized:
        if capture_image():
            print("Image captured successfully.")
        else:
            print("Failed to capture image.")
    else:
        print("Camera not initialized or directory creation failed.")

def signal_handler(sig, frame):
    print("\nShutting down...")
    if picam2:
        picam2.stop()
    if button:
        button.close()
    if led:
        led.close()
    sys.exit(0)

def main():
    global camera_initialized, button
    setup_gpio()
    setup_camera()
    if not camera_initialized:
        print("Camera initialization failed. Exiting.")
        return

    try:
        while True:
            if button.is_pressed:
                time.sleep(DEBOUNCE_DELAY)
                if button.is_pressed:
                    handle_button_press()
            time.sleep(MAIN_LOOP_PAUSE)
    except KeyboardInterrupt:
        print("\nKeyboardInterrupt received. Shutting down...")
    finally:
        if picam2:
            picam2.stop()
        if button:
            button.close()
        if led:
            led.close()
        print("All resources released.")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

