OLED_I2C_ADDRESS = 0x3C

# Initialize I2C bus in a try/finally block to ensure release
def initialize_i2c_bus():
    try:
        # Attempt to open I2C bus
        bus = SMBus(I2C_BUS)
        # Check if OLED is connected (optional, not required for the task)
        try:
            bus.read_byte_data(OLED_I2C_ADDRESS, 0x00)
        except Exception as e:
            print(f"OLED not found or not accessible at address {OLED_I2C_ADDRESS}: {e}")
        return bus
    except Exception as e:
        print(f"Failed to initialize I2C bus {I2C_BUS}: {e}")
        return None

# Signal handler to ensure I2C bus is released on exit
def signal_handler(sig, frame):
    print("\nReceived exit signal, releasing I2C bus...")
    if 'bus' in globals():
        try:
            bus.close()
        except Exception as e:
            print(f"Error closing I2C bus: {e}")
    sys.exit(0)

# Register signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Main loop
def main():
    global bus
    bus = initialize_i2c_bus()
    if not bus:
        print("I2C bus initialization failed. Exiting.")
        return

    try:
        while True:
            try:
                # Read temperature from thermal zone file
                with open("/sys/class/thermal/thermal_zone0/temp", "r") as temp_file:
                    temp_millideg = int(temp_file.read())
                    temp_celsius = temp_millideg / 1000.0
                    print(f"Current temperature: {temp_celsius:.2f}°C")
            except FileNotFoundError:
                print("Thermal zone file not found. Check if the system supports it.")
            except PermissionError:
                print("Permission denied when reading thermal zone file.")
            except Exception as e:
                print(f"Unexpected error reading temperature: {e}")

            # Wait for 2 seconds
            time.sleep(2)
    except KeyboardInterrupt:
        print("\nUser interrupted the program.")
    finally:
        if 'bus' in globals():
            try:
                bus.close()
            except Exception as e:
                print(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
