import os
import logging
import signal
import time
from contextlib import contextmanager
from PIL import Image, ImageSequence
import warnings

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class AnimatedGif:
    def __init__(self, display, width=None, height=None, folder_path=None):
        self.display = display
        self.width = width
        self.height = height
        self.folder_path = folder_path
        self.frames = []
        self.loop_count = 0
        self._is_running = True
        self._file_list = []

        # Set default dimensions if not provided
        if self.width is None:
            self.width = self.display.width
        if self.height is None:
            self.height = self.display.height

        # Validate folder path
        if self.folder_path is None or not os.path.isdir(self.folder_path):
            raise FileNotFoundError("Folder path is invalid or not provided.")

        # Load valid GIF files
        self.load_files()

    def load_files(self):
        self._file_list = []
        for filename in os.listdir(self.folder_path):
            if filename.lower().endswith('.gif'):
                file_path = os.path.join(self.folder_path, filename)
                try:
                    with Image.open(file_path) as img:
                        if img.is_animated:
                            self._file_list.append(file_path)
                            logging.info(f"Valid GIF found: {filename}")
                        else:
                            logging.warning(f"File {filename} is not an animated GIF.")
                except Exception as e:
                    logging.error(f"Error reading {filename}: {str(e)}")
        if not self._file_list:
            raise FileNotFoundError("No valid GIF files found in the specified folder.")

    def preload(self):
        self.frames = []
        for file_path in self._file_list:
            try:
                with Image.open(file_path) as img:
                    self.loop_count = img.info.get('loop', 0)
                    frames = ImageSequence.Iterator(img)
                    for frame in frames:
                        frame = frame.convert('RGB')
                        frame = frame.resize((self.width, self.height), Image.NEAREST)
                        self.frames.append(frame)
            except Exception as e:
                logging.error(f"Error preloading {file_path}: {str(e)}")
                continue

    def play(self):
        if not self.frames:
            logging.error("No frames to play.")
            return False

        frame_index = 0
        loop_count = self.loop_count
        start_time = time.monotonic()
        while self._is_running and (loop_count == 0 or loop_count > 0):
            try:
                frame = self.frames[frame_index]
                self.display.display(frame)
                frame_duration = self.frames[frame_index].info.get('duration', 100)  # Default 100ms
                sleep_time = (frame_duration / 1000) - (time.monotonic() - start_time)
                if sleep_time > 0:
                    time.sleep(sleep_time)
                else:
                    logging.warning("Sleep time would be negative, skipping.")
                frame_index = (frame_index + 1) % len(self.frames)
                loop_count -= 1
            except Exception as e:
                logging.error(f"Error during playback: {str(e)}")
                return False
        return True

    def run(self):
        while self._is_running:
            try:
                if self.play():
                    logging.info("GIF playback completed.")
                else:
                    logging.warning("GIF playback failed or no frames available.")
            except Exception as e:
                logging.error(f"Error in run loop: {str(e)}")
            finally:
                self._is_running = False

    def stop(self):
        self._is_running = False

@contextmanager
def handle_signal(display, animated_gif):
    try:
        signal.signal(signal.SIGINT, lambda signum, frame: animated_gif.stop())
        signal.signal(signal.SIGTERM, lambda signum, frame: animated_gif.stop())
        yield
    finally:
        signal.signal(signal.SIGINT, signal.SIG_DFL)
