class GifPlayer:
    def __init__(self, display_bus, display_size=(240, 240), gif_folder="gifs", mqtt_topic="gif_player"):
        self.display_bus = display_bus
        self.display_size = display_size
        self.gif_folder = gif_folder
        self.mqtt_topic = mqtt_topic
        self.mqtt_client = None
        self.gifs = []
        self.current_gif_index = 0
        self.running = True
        self.display = None
        self.frame_timer = None
        self.frame_index = 0
        self.frame_duration = 0
        self.frame_data = None
        self.lock = threading.Lock()

        self._init_display()
        self._init_mqtt()
        self._load_gifs()

    def _init_display(self):
        try:
            # Initialize SPI bus and display
            spi = SPIBus(spi_bus=0, baudrate=40000000, polarity=0, phase=0)
            self.display = ST7789(
                spi,
                width=self.display_size[0],
                height=self.display_size[1],
                rotation=90,
                backlight_pin=18
            )
            self.display.fill(0)
            logging.info("Display initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize display: {e}")
            sys.exit(1)

    def _init_mqtt(self):
        try:
            self.mqtt_client = Client()
            self.mqtt_client.connect("localhost", 1883, 60)
            self.mqtt_client.subscribe(self.mqtt_topic)
            self.mqtt_client.on_message = self._on_mqtt_message
            logging.info("MQTT client initialized.")
        except Exception as e:
            logging.error(f"Failed to initialize MQTT client: {e}")
            sys.exit(1)

    def _on_mqtt_message(self, client, userdata, msg):
        if msg.topic == self.mqtt_topic:
            try:
                payload = msg.payload.decode()
                if payload == "play":
                    self.run()
                elif payload == "stop":
                    self.running = False
            except Exception as e:
                logging.error(f"MQTT message error: {e}")

    def _load_gifs(self):
        if not os.path.exists(self.gif_folder):
            logging.error(f"Folder '{self.gif_folder}' does not exist.")
            sys.exit(1)

        self.gifs = [f for f in os.listdir(self.gif_folder) if f.endswith(".gif")]
        if not self.gifs:
            logging.error(f"No GIF files found in folder '{self.gif_folder}'.")
            sys.exit(1)

        for gif in self.gifs:
            try:
                with Image.open(os.path.join(self.gif_folder, gif)) as img:
                    if img.format != "GIF":
                        logging.warning(f"File '{gif}' is not a GIF.")
                        continue
                    img.seek(0)
                    self.gifs.remove(gif)
                    self.gifs.append(gif)
            except Exception as e:
                logging.error(f"Failed to read GIF '{gif}': {e}")
                sys.exit(1)

    def _convert_frame_to_rgb(self, frame):
        try:
            frame = frame.convert("RGB")
            width, height = self.display_size
            frame = frame.resize((width, height), Image.LANCZOS)
            return frame
        except Exception as e:
            logging.error(f"Failed to convert frame: {e}")
            return None

    def _get_frame_duration(self, frame):
        try:
            if hasattr(frame, "duration"):
                return frame.duration
            return 100  # Default duration in milliseconds
        except Exception as e:
            logging.error(f"Failed to get frame duration: {e}")
            return 100

    def play(self, gif_index):
        if gif_index < 0 or gif_index >= len(self.gifs):
            logging.error(f"Invalid GIF index: {gif_index}")
            return

        gif_path = os.path.join(self.gif_folder, self.gifs[gif_index])
        try:
            with Image.open(gif_path) as img:
                self.frame_index = 0
                self.frame_duration = self._get_frame_duration(img)
                self.frame_data = self._convert_frame_to_rgb(img)
                self.current_gif_index = gif_index
                self._display_frame()
        except Exception as e:
            logging.error(f"Failed to play GIF '{self.gifs[gif_index]}': {e}")

    def _display_frame(self):
        if not self.frame_data:
            return

        try:
            self.display.display(self.frame_data)
        except Exception as e:
            logging.error(f"Failed to display frame: {e}")

    def run(self):
        if not self.running:
            return

        try:
            while self.running:
                for i in range(len(self.gifs)):
                    self.play(i)
                    time.sleep(self.frame_duration / 1000)
                time.sleep(1)
        except KeyboardInterrupt:
            logging.info("Received SIGINT, stopping...")
        except Exception as e:
            logging.error(f"Error in run loop: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.display:
            self.display.fill(0)
            self.display.deinit()
            logging.info("Display resources released.")
        if self.mqtt_client:
            self.mqtt_client.disconnect()
            logging.info("MQTT client disconnected.")
        self.running = False

    def __del__(self):
        self.cleanup()

def main():
    display_bus = SPIBus(spi_bus=0, baudrate=40000000, polarity=0, phase=0)
    player = GifPlayer(display_bus, display_size=(240, 240), gif_folder="gifs")
    player.run()

if __name__ == "__main__":
    main()

