import time
import RPi.GPIO as GPIO
from signal import signal, SIGINT

# GPIO pin definitions
TRIGGER_PIN = 23
ECHO_PIN = 24
LED_PIN = 18

# Constants
TRIGGER_DURATION = 0.00001  # 10 microseconds
MAX_WAIT_TIME = 0.05  # 0.05 seconds
DISTANCE_THRESHOLD = 10  # 10 cm
MEASUREMENT_INTERVAL = 1  # 1 second

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(TRIGGER_PIN, GPIO.OUT)
    GPIO.setup(ECHO_PIN, GPIO.IN)
    GPIO.setup(LED_PIN, GPIO.OUT)

def cleanup_gpio():
    GPIO.cleanup()

def trigger_pulse():
    GPIO.output(TRIGGER_PIN, True)
    time.sleep(TRIGGER_DURATION)
    GPIO.output(TRIGGER_PIN, False)

def measure_distance():
    trigger_pulse()
    start_time = time.time()
    while GPIO.input(ECHO_PIN) == 0:
        if time.time() - start_time > MAX_WAIT_TIME:
            raise TimeoutError("Echo signal timeout")
    pulse_start = time.time()
    while GPIO.input(ECHO_PIN) == 1:
        if time.time() - start_time > MAX_WAIT_TIME:
            raise TimeoutError("Echo signal timeout")
    pulse_end = time.time()
    pulse_duration = pulse_end - pulse_start
    distance_cm = (pulse_duration * 17150)  # Speed of sound in cm/s
    return distance_cm

def control_led(distance_cm):
    if distance_cm < DISTANCE_THRESHOLD:
        GPIO.output(LED_PIN, GPIO.HIGH)
    else:
        GPIO.output(LED_PIN, GPIO.LOW)

def main():
    try:
        setup_gpio()
        while True:
            try:
                distance = measure_distance()
                print(f"Distance: {distance:.2f} cm")
                control_led(distance)
            except TimeoutError as e:
                print(f"Sensor error: {e}")
            time.sleep(MEASUREMENT_INTERVAL)
    except KeyboardInterrupt:
        print("\nKeyboard interrupt received. Cleaning up...")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

import time
import signal
import logging
from gpiozero import Device, DigitalInputDevice
from smbus2 import SMBus, i2c_msg
from threading import Thread, Event

# Configuration
I2C_ADDRESS = 0x20  # Default I2C address for PCF8574
SENSOR_COUNT = 8
POLL_INTERVAL = 0.1  # 100 ms
RETRY_DELAY = 1.0
LOG_FORMAT = '%(asctime)s - %(levelname)s - %(message)s'

# Setup logging
logging.basicConfig(level=logging.INFO, format=LOG_FORMAT)

# Global variables
i2c_bus = None
stop_flag = Event()
error_occurred = Event()

def setup_i2c():
    try:
        global i2c_bus
        i2c_bus = SMBus(1)  # Use I2C bus 1 (physical pins 3 and 5)
        logging.info("I2C bus initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus: {e}")
        raise

def read_sensor_values():
    try:
        # Read 8 bits from the I2C device
        data = i2c_bus.read_byte(I2C_ADDRESS)
        return data
    except Exception as e:
        logging.error(f"I2C read error: {e}")
        raise

def check_sensors():
    try:
        data = read_sensor_values()
        for sensor_num in range(SENSOR_COUNT):
            if not (data & (1 << sensor_num)):
                logging.info(f"Obstacle detected by sensor {sensor_num}")
    except Exception as e:
        logging.error(f"Error checking sensors: {e}")
        error_occurred.set()

def poll_sensors():
    while not stop_flag.is_set():
        try:
            check_sensors()
        except Exception as e:
            logging.error(f"Polling error: {e}")
            error_occurred.set()
        time.sleep(POLL_INTERVAL)

def signal_handler(sig, frame):
    logging.info("Shutting down gracefully...")
    stop_flag.set()
    error_occurred.set()
    if i2c_bus:
        i2c_bus.close()
    time.sleep(1)  # Allow time for any pending operations

def main():
    setup_i2c()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    poll_thread = Thread(target=poll_sensors, daemon=True)
    poll_thread.start()

    try:
        while not stop_flag.is_set():
            if error_occurred.is_set():
                logging.error("Retrying after error...")
                time.sleep(RETRY_DELAY)
                error_occurred.clear()
                try:
                    setup_i2c()
                except Exception as e:
                    logging.error(f"Failed to reinitialize I2C: {e}")
                    break
            time.sleep(0.1)
    except KeyboardInterrupt:
        logging.info("Main loop interrupted by user.")
    finally:
        logging.info("Cleaning up resources...")
        if i2c_bus:
            i2c_bus.close()
        stop_flag.set()
        poll_thread.join(timeout=1)

if __name__ == "__main__":
    main()

import time
import logging
import subprocess
import re
from datetime import datetime
from gpiozero import DigitalInputDevice, DeviceIgnored
from threading import Thread
import signal
import sys

# Constants
LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75
LOG_FORMAT = "%(asctime)s - %(message)s"
LOG_FILE = "energy_monitor.log"

# Setup logging
logging.basicConfig(filename=LOG_FILE, level=logging.INFO, format=LOG_FORMAT)

def setup_logging():
    """Set up logging configuration."""
    logging.info("Starting energy monitoring system")

def simulate_light_sensor():
    """Simulate light sensor on GPIO17 (BCM)."""
    try:
        # Simulate light levels based on time of day
        now = datetime.now()
        hour = now.hour
        if 6 <= hour < 18:
            # Daylight: 600-1000 lux
            lux = 600 + (1000 - 600) * (hour - 6) / 12
        else:
            # Nighttime: 100-300 lux
            lux = 100 + (300 - 100) * (hour - 18) / 6
        return lux
    except Exception as e:
        logging.error(f"Error simulating light sensor: {e}")
        return 0

def simulate_temperature_sensor():
    """Simulate temperature sensor on GPIO4 (BCM)."""
    try:
        # Simulate temperature between 20-30°C
        temp = 20 + (30 - 20) * (datetime.now().second / 60)
        return temp
    except Exception as e:
        logging.error(f"Error simulating temperature sensor: {e}")
        return 0

def read_pi_temperature():
    """Read Raspberry Pi internal temperature via vcgencmd."""
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            match = re.search(r"temp=(\d+\.\d+)'C", result.stdout)
            if match:
                return float(match.group(1))
        logging.warning("Failed to read Pi temperature")
        return None
    except Exception as e:
        logging.error(f"Error reading Pi temperature: {e}")
        return None

def log_data(light, temperature, voltage, current, pi_temp):
    """Log the sensor data with timestamp."""
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        log_line = f"{timestamp} - Light: {light} lux, Temperature: {temperature} °C, Voltage: {voltage} V, Current: {current} A, Pi Temp: {pi_temp} °C"
        logging.info(log_line)
    except Exception as e:
        logging.error(f"Error logging data: {e}")

def check_warnings(light, temperature, pi_temp):
    """Check for warnings and simulate system responses."""
    try:
        if light < LOW_LIGHT_THRESHOLD:
            logging.warning(f"WARNING: Low light level detected: {light} lux")
        if temperature > HIGH_TEMP_THRESHOLD:
            logging.warning(f"WARNING: High temperature detected: {temperature} °C, cooling activated")
        if pi_temp is not None and pi_temp > HIGH_PI_TEMP_THRESHOLD:
            logging.critical(f"CRITICAL: Pi temperature too high: {pi_temp} °C, system shutdown simulated")
    except Exception as e:
        logging.error(f"Error checking warnings: {e}")

def simulate_voltage_and_current(light):
    """Simulate voltage and current based on light level."""
    try:
        if light > LOW_LIGHT_THRESHOLD:
            voltage = 11.5 + (12.5 - 11.5) * (light - LOW_LIGHT_THRESHOLD) / (1000 - LOW_LIGHT_THRESHOLD)
            current = 1.5 + (2.5 - 1.5) * (light - LOW_LIGHT_THRESHOLD) / (1000 - LOW_LIGHT_THRESHOLD)
        else:
            voltage = 10.0 + (11.0 - 10.0) * (light - 100) / (300 - 100)
            current = 0.5 + (1.0 - 0.5) * (light - 100) / (300 - 100)
        return voltage, current
    except Exception as e:
        logging.error(f"Error simulating voltage and current: {e}")
        return 0.0, 0.0

def cleanup_gpio(gpio_devices):
    """Clean up GPIO resources."""
    for device in gpio_devices:
        try:
            device.close()
        except Exception as e:
            logging.error(f"Error closing GPIO device: {e}")

def main():
    setup_logging()
