        return None
    except Exception as e:
        logging.error(f"Error reading Pi temperature: {e}")
        return None

def log_data(light, temperature, voltage, current, pi_temp):
    """Log the sensor data with timestamp."""
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        log_line = f"{timestamp} - Light: {light} lux, Temperature: {temperature} °C, Voltage: {voltage} V, Current: {current} A, Pi Temp: {pi_temp} °C"
        logging.info(log_line)
    except Exception as e:
        logging.error(f"Error logging data: {e}")

def check_warnings(light, temperature, pi_temp):
    """Check for warnings and simulate system responses."""
    try:
        if light < LOW_LIGHT_THRESHOLD:
            logging.warning(f"WARNING: Low light level detected: {light} lux")
        if temperature > HIGH_TEMP_THRESHOLD:
            logging.warning(f"WARNING: High temperature detected: {temperature} °C, cooling activated")
        if pi_temp is not None and pi_temp > HIGH_PI_TEMP_THRESHOLD:
