def simulate_voltage_and_current(light):
    """Simulate voltage and current based on light level."""
    try:
        if light > LOW_LIGHT_THRESHOLD:
            voltage = 11.5 + (12.5 - 11.5) * (light - LOW_LIGHT_THRESHOLD) / (1000 - LOW_LIGHT_THRESHOLD)
