from gpiozero import Device, DigitalInputDevice, DeviceError
from threading import Lock
from typing import Tuple, Optional, Any

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# CRC-8 polynomial and initial value for DHT20
CRC8_POLY = 0x31
CRC8_INIT = 0xFF

class DHT20:
    def __init__(self, i2c_bus: int = 1, i2c_address: int = 0x38):
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self.bus = None
        self.lock = Lock()
        self._initialize_bus()

    def _initialize_bus(self):
        try:
            self.bus = SMBus(self.i2c_bus)
        except Exception as e:
            logging.error(f"Failed to open I2C bus {self.i2c_bus}: {e}")
            self.bus = None

    def _close_bus(self):
        if self.bus:
            self.bus.close()
            self.bus = None

    def __del__(self):
        self.cleanup()

    def cleanup(self):
        with self.lock:
            self._close_bus()

    def _wait_for_power_stabilization(self):
        time.sleep(0.5)

    def _read_status_register(self) -> int:
        with self.lock:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            try:
                msg = i2c_msg.write(self.i2c_address, [0x00])
                self.bus.i2c_rdwr(msg)
                msg = i2c_msg.read(self.i2c_address, 1)
                self.bus.i2c_rdwr(msg)
                status = list(msg)[0]
                return status
            except Exception as e:
                logging.error(f"I2C read error: {e}")
                raise

    def _verify_status_register(self, status: int) -> bool:
        # DHT20 status register: bit 7 is busy, bit 6 is error
        # Mask with 0x80 to check if busy
        if (status & 0x80) != 0:
            logging.warning("Sensor is busy, retrying...")
            return False
        return True

    def _read_data(self) -> Tuple[int, int, int]:
        with self.lock:
            if not self.bus:
                raise RuntimeError("I2C bus not initialized")
            try:
                # Start measurement
                msg = i2c_msg.write(self.i2c_address, [0x01])
                self.bus.i2c_rdwr(msg)
                time.sleep(0.05)  # Wait for measurement to complete

                # Read data
                msg = i2c_msg.read(self.i2c_address, 7)
                self.bus.i2c_rdwr(msg)
                data = list(msg)
                return data[0], data[1], data[2], data[3], data[4], data[5], data[6]
            except Exception as e:
                logging.error(f"I2C read error: {e}")
                raise

    def _compute_crc8(self, data: bytes) -> int:
        crc = crcmod.precompute(CRC8_POLY, CRC8_INIT)
        return crc(data[:6])

    def _parse_data(self, data: bytes) -> Tuple[float, float, bool]:
        humidity_raw = (data[1] << 12) | (data[2] << 4) | (data[3] >> 4)
        temperature_raw = (data[3] & 0x0F) << 12 | (data[4] << 4) | (data[5] >> 4)
        crc = data[6]

        # Compute CRC
        computed_crc = self._compute_crc8(data[:6])
        crc_error = computed_crc != crc

        # Convert to human-readable units
        humidity = humidity_raw / 10880.0 * 100.0
        temperature = temperature_raw / 10880.0 - 50.0

        return temperature, humidity, crc_error

    def _poll_status(self, max_retries: int = 5, timeout: float = 0.1) -> bool:
        for attempt in range(max_retries):
            try:
                status = self._read_status_register()
                if self._verify_status_register(status):
                    return True
                time.sleep(timeout)
            except Exception as e:
                logging.error(f"Status check failed: {e}")
                return False
        logging.warning("Status check timeout after 5 attempts")
        return False

    def read(self) -> Tuple[Optional[float], Optional[float], bool]:
        with self.lock:
            if not self.bus:
                logging.error("I2C bus not initialized")
                return (None, None, True)

            try:
                self._wait_for_power_stabilization()
                if not self._poll_status():
                    logging.error("Failed to poll status register")
                    return (None, None, True)

                data = self._read_data()
                temperature, humidity, crc_error = self._parse_data(data)
                return (temperature, humidity, crc_error)
            except Exception as e:
                logging.error(f"Sensor read failed: {e}")
                return (None, None, True)

    def read_with_retry(self) -> Tuple[Optional[float], Optional[float], bool]:
        with self.lock:
            if not self.bus:
                logging.error("I2C bus not initialized")
                return (None, None, True)

            for attempt in range(5):
                try:
                    self._wait_for_power_stabilization()
                    if not self._poll_status():
                        logging.warning("Status check failed, retrying...")
                        time.sleep(2)
                        continue

                    data = self._read_data()
                    temperature, humidity, crc_error = self._parse_data(data)
                    return (temperature, humidity, crc_error)
                except Exception as e:
                    logging.error(f"Sensor read failed: {e}")
                    if attempt < 4:
                        time.sleep(2)
                    else:
                        return (None, None, True)
            return (None, None, True)

