            data.append(1 if pulse_duration > 0.00007 else 0)

        if len(data) != 40:
            return (None, None)

        humidity = 0
        temperature = 0
        checksum = 0

        for i in range(16):
            humidity = (humidity << 1) | data[i]

        for i in range(16, 32):
            temperature = (temperature << 1) | data[i]

        for i in range(32, 40):
            checksum = (checksum << 1) | data[i]

        if (humidity + temperature) != checksum:
            return (None, None)

        humidity = humidity / 10.0
        temperature = temperature / 10.0

        if temperature >= 256:
            temperature -= 256
            if temperature >= 128:
                temperature -= 256
                if temperature < 0:
                    temperature = -temperature
                else:
                    temperature = -temperature
        else:
            if temperature >= 128:
                temperature -= 256
                temperature = -temperature

        return (temperature, humidity)

    def read(self):
        if time.time() - self.last_read < LOG_INTERVAL:
            return (self.temperature, self.humidity)

        self.temperature, self.humidity = self._read_data()
        self.last_read = time.time()
        return (self.temperature, self.humidity)

    def cleanup(self):
        self.output.close()
        self.input.close()

def log_data(dht):
    while True:
        try:
            temp, hum = dht.read()
            if temp is not None and hum is not None:
                now = datetime.now().strftime(CSV_FORMAT)
                with open(LOG_FILE, "a", newline="") as f:
                    writer = csv.writer(f)
                    writer.writerow([now, temp, hum])
            time.sleep(LOG_INTERVAL)
        except Exception as e:
            logging.error(f"Error logging data: {e}")
            time.sleep(LOG_INTERVAL)

def signal_handler(sig, frame):
    logging.info("Shutting down...")
    dht.cleanup()
    sys.exit(0)

def main():
    dht = DHT22(DHT_PIN)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        log_thread = Thread(target=log_data, daemon=True, args=(dht,))
        log_thread.start()
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        signal_handler(None, None)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        dht.cleanup()
    finally:
        dht.cleanup()

if __name__ == "__main__":
    main()
