import smbus2
import os

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# CRC-8 polynomial: 0x31 (x^8 + x^5 + x^4 + 1)
crc8_func = crcmod.predefined.Crc('crc-8-ibm')

# DHT20 register addresses
DHT20_STATUS_REGISTER = 0x00
DHT20_MEASURE_REGISTER = 0x08
DHT20_HUMIDITY_REGISTER = 0x01
DHT20_TEMPERATURE_REGISTER = 0x02
DHT20_CRC_REGISTER = 0x06

class DHT20Status(IntEnum):
    MEASURING = 0x80
    DATA_READY = 0x00
    ERROR = 0x40

class DHT20Sensor:
    def __init__(self, i2c_bus: int = 1):
        self.bus = None
        self.i2c_bus = i2c_bus
        self._init_bus()

    def _init_bus(self):
        try:
            self.bus = smbus2.SMBus(self.i2c_bus)
            # Verify sensor by reading status register
            status = self._read_register(DHT20_STATUS_REGISTER)
            if status != 0x80:
                logging.error("DHT20 sensor not found or not responding.")
                self.bus = None
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus or verify sensor: {e}")
            self.bus = None

    def _read_register(self, reg: int) -> int:
        if not self.bus:
            raise RuntimeError("I2C bus not initialized.")
        try:
            return self.bus.read_byte_data(0x38, reg)
        except Exception as e:
            logging.error(f"I2C read error: {e}")
            self.bus = None
            raise

    def _write_register(self, reg: int, value: int):
        if not self.bus:
            raise RuntimeError("I2C bus not initialized.")
        try:
            self.bus.write_byte_data(0x38, reg, value)
        except Exception as e:
            logging.error(f"I2C write error: {e}")
            self.bus = None
            raise

    def measure(self) -> Tuple[Optional[float], Optional[float], bool]:
        if not self.bus:
            return (None, None, True)

        try:
            # Start measurement
            self._write_register(DHT20_MEASURE_REGISTER, 0x00)
            start_time = time.time()

            # Wait for data to be ready
            while time.time() - start_time < 0.1:
                status = self._read_register(DHT20_STATUS_REGISTER)
                if status == DHT20Status.DATA_READY:
                    break
                elif status == DHT20Status.ERROR:
                    logging.error("DHT20 measurement error.")
                    return (None, None, True)
                time.sleep(0.01)

            # Read data
            humidity_bytes = self.bus.read_i2c_block_data(0x38, DHT20_HUMIDITY_REGISTER, 3)
            temperature_bytes = self.bus.read_i2c_block_data(0x38, DHT20_TEMPERATURE_REGISTER, 3)
            crc_byte = self._read_register(DHT20_CRC_REGISTER)

            # Extract raw values
            humidity_raw = (humidity_bytes[0] << 16) | (humidity_bytes[1] << 8) | humidity_bytes[2]
            temperature_raw = (temperature_bytes[0] << 16) | (temperature_bytes[1] << 8) | temperature_bytes[2]

            # Compute CRC-8
            data_to_crc = humidity_bytes + temperature_bytes
            crc_calculated = crc8_func.calculate(bytes(data_to_crc))
            crc_error = crc_calculated != crc_byte

            # Convert to actual values
            humidity = humidity_raw / 108800.0 * 100.0
            temperature = temperature_raw / 20000.0

            return (temperature, humidity, crc_error)

        except Exception as e:
            logging.error(f"Measurement error: {e}")
            return (None, None, True)

    def close(self):
        if self.bus:
            try:
                self.bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            self.bus = None

def signal_handler(sig, frame):
    logging.info("Received signal, closing I2C bus...")
    sensor.close()
    sys.exit(0)

if __name__ == "__main__":
    sensor = DHT20Sensor(i2c_bus=1)
    if sensor.bus:
        try:
            signal.signal(signal.SIGINT, signal_handler)
            signal.signal(signal.SIGTERM, signal_handler)
            temperature, humidity, crc_error = sensor.measure()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%RH, CRC Error: {crc_error}")
            else:
                print("Measurement failed.")
        finally:
            sensor.close()
    else:
        print("Failed to initialize DHT20 sensor.")

