import argparse
import socket
import json
import logging
import sys
import signal
import time
from gpiozero import DigitalOutputDevice
from gpiozero import DeviceAlreadyClaimed
from datetime import datetime

# Constants
DEFAULT_RELAY_PIN = 17
DEFAULT_DHT_PIN = 4
DEFAULT_PORT = 12345
DEFAULT_ALLOWED_IP = "192.168.1.100"
DEFAULT_LOG_FILE = "hydroponics_controller.log"

# Setup logging
def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )

# Handle signals for graceful shutdown
def signal_handler(sig, frame):
    logging.info("Shutting down gracefully...")
    if 'relay' in globals():
        relay.close()
    if 'server_socket' in globals():
        server_socket.close()
    sys.exit(0)

# Simulated DHT11 sensor
def get_temperature():
    return 25.0

# Pump control
def toggle_pump(state):
    if state == "on":
        relay.on()
    elif state == "off":
        relay.off()

# Process incoming JSON commands
def handle_client(conn):
    try:
        data = conn.recv(1024)
        if not data:
            return
        command = json.loads(data.decode('utf-8'))
        logging.info(f"Received command: {command}")

        if command.get("command") == "pump_on":
            toggle_pump("on")
            response = {"status": "on", "temperature": 25.0}
        elif command.get("command") == "pump_off":
            toggle_pump("off")
            response = {"status": "off", "temperature": 25.0}
        elif command.get("command") == "get_status":
            response = {"status": "on" if relay.value else "off", "temperature": 25.0}
        else:
            response = {"error": "Invalid command"}
            logging.warning("Invalid command received")

        conn.send(json.dumps(response).encode('utf-8'))
    except json.JSONDecodeError:
        logging.error("Malformed JSON received")
    except Exception as e:
        logging.error(f"Error processing command: {e}")

# Main function
def main():
    parser = argparse.ArgumentParser(description="Hydroponics Controller")
    parser.add_argument("--relay-pin", type=int, default=DEFAULT_RELAY_PIN, help="BCM pin for relay")
    parser.add_argument("--dht-pin", type=int, default=DEFAULT_DHT_PIN, help="BCM pin for DHT11")
    parser.add_argument("--port", type=int, default=DEFAULT_PORT, help="TCP port to listen on")
    parser.add_argument("--allowed-ip", type=str, default=DEFAULT_ALLOWED_IP, help="Allowed IP address")
    parser.add_argument("--log-file", type=str, default=DEFAULT_LOG_FILE, help="Path to log file")
    args = parser.parse_args()

    setup_logging(args.log_file)

    try:
        relay = DigitalOutputDevice(args.relay_pin, initial_value=False)
    except DeviceAlreadyClaimed:
        logging.error(f"GPIO pin {args.relay_pin} is already in use.")
        sys.exit(1)
    except Exception as e:
        logging.error(f"Failed to initialize relay on pin {args.relay_pin}: {e}")
        sys.exit(1)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(('0.0.0.0', args.port))
        server_socket.listen(1)
        logging.info(f"Server listening on port {args.port}...")

        while True:
            client_socket, addr = server_socket.accept()
            if addr[0] != args.allowed_ip:
                logging.warning(f"Connection from unauthorized IP: {addr[0]}")
                client_socket.close()
                continue
            logging.info(f"Connection from {addr[0]}")
            handle_client(client_socket)
            client_socket.close()
    except socket.error as e:
        logging.error(f"Socket error: {e}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if 'relay' in globals():
            relay.close()
        if 'server_socket' in globals():
            server_socket.close()

if __name__ == "__main__":
    main()

