import time
import psutil
import signal
import sys

def get_cpu_temperature():
    """Lazy function to read CPU temperature, creating the sensor object on demand."""
    try:
        # Use psutil to get CPU temperature (this is a workaround for the lack of direct access to /sys/class/thermal)
        # Note: This method may not be accurate or available on all systems, but it's a common approach.
        # For more accurate readings, you may need to use a different method or install additional tools.
        temps = psutil.sensors_temperatures()
        if 'coretemp' in temps:
            cpu_temp = temps['coretemp'][0].current
            return cpu_temp
        else:
            raise FileNotFoundError("Thermal sensor not found")
    except Exception as e:
        raise e

def read_cpu_temperature():
    """Reads the CPU temperature and returns it, handling errors gracefully."""
    try:
        temp = get_cpu_temperature()
        return round(temp, 2)
    except FileNotFoundError as e:
        print(f"Error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error: {e}")
        return None

def signal_handler(sig, frame):
    """Handle keyboard interrupt and exit cleanly."""
    print("\nProgram terminated")
    sys.exit(0)

def main():
    # Register signal handler for keyboard interrupt
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    while True:
        temp = read_cpu_temperature()
        if temp is not None:
            print(f"CPU Temperature: {temp:.2f} °C")
        else:
            print("Failed to read CPU temperature")
        time.sleep(5)

if __name__ == "__main__":
    main()

