TEMP_MAX = 35
UPDATE_INTERVAL = 5  # seconds
FAILURE_RATE = 0.10
MAX_FAILURES = 3
PWM_FREQ = 50
PWM_DUTY_CYCLE = 0
STEP_SIZE = 5
DELAY_BETWEEN_STEPS = 0.1

# Setup logging
logging.basicConfig(filename=LOG_FILE, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize GPIO and PWM
pin_factory = PiGPIOFactory()
servo1 = Servo(SERVO_PIN_1, pin_factory=pin_factory)
servo2 = Servo(SERVO_PIN_2, pin_factory=pin_factory)

# Initialize failure counters
failure_count = 0
use_alternate_api = False

def log_message(message, level=logging.INFO):
    logging.log(level, message)

def generate_temperature():
    return random.uniform(TEMP_MIN, TEMP_MAX)

def map_temperature_to_angle(temp):
    if temp < 20:
        return 0
    elif 20 <= temp < 25:
        return 45
    elif 25 <= temp < 30:
        return 90
    elif 30 <= temp < 35:
        return 135
    else:
        return 180

def move_servo(servo, target_angle, step_size=STEP_SIZE, delay=DELAY_BETWEEN_STEPS):
    global failure_count, use_alternate_api
    current_angle = servo.angle
    if current_angle is None:
        current_angle = 0
    if target_angle == current_angle:
        return True
    steps = (target_angle - current_angle) // step_size
    if steps == 0:
