    for i in range(abs(steps)):
        direction = 1 if target_angle > current_angle else -1
        new_angle = current_angle + direction * step_size
        try:
            servo.angle = new_angle
            time.sleep(delay)
            current_angle = new_angle
        except Exception as e:
            log_message(f"Servo movement failed: {str(e)}", logging.ERROR)
            failure_count += 1
            if failure_count >= MAX_FAILURES and not use_alternate_api:
                log_message("Switching to alternate API due to consecutive failures", logging.INFO)
                use_alternate_api = True
            return False
    return True

def main():
    global failure_count, use_alternate_api
    try:
        while True:
            temp = generate_temperature()
            log_message(f"Temperature reading: {temp:.2f}°C", logging.INFO)
            target_angle = map_temperature_to_angle(temp)
            log_message(f"Target angle: {target_angle}°", logging.INFO)

            if not use_alternate_api:
                if not move_servo(servo1, target_angle):
                    log_message("Failed to move servo 1", logging.WARNING)
                if not move_servo(servo2, target_angle):
                    log_message("Failed to move servo 2", logging.WARNING)
            else:
                log_message("Using alternate API (simulated)", logging.INFO)
                # Simulate alternate API movement
                if random.random() < FAILURE_RATE:
                    log_message("Alternate API movement failed", logging.WARNING)
                else:
                    log_message("Alternate API movement successful", logging.INFO)

            time.sleep(UPDATE_INTERVAL)
    except KeyboardInterrupt:
        log_message("Received KeyboardInterrupt, cleaning up...", logging.INFO)
    except Exception as e:
        log_message(f"Unexpected error: {str(e)}", logging.CRITICAL)
    finally:
        try:
            if not use_alternate_api:
                servo1.angle = 0
                servo2.angle = 0
            log_message("Stopping PWM signals and cleaning up GPIO", logging.INFO)
            servo1.close()
            servo2.close()
            pin_factory.close()
        except Exception as e:
            log_message(f"Error during cleanup: {str(e)}", logging.ERROR)

