import paho.mqtt.client as mqtt

# Configuration
MQTT_BROKER = "mqtt.broker.address"
MQTT_PORT = 1883
MQTT_TOPIC = "wildlife/monitoring"
LOG_FILE = "wildlife_monitoring.log"
GPIO_PIN_1 = 4
GPIO_PIN_2 = 17
MAX_RETRIES = 3
RETRY_DELAY = 2  # seconds
NORMAL_TEMP_RANGE = (10, 35)  # in Celsius
NORMAL_HUMIDITY_RANGE = (20, 80)  # in percentage

# Setup logging
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Initialize GPIO with pigpio for better reliability
pin_factory = PiGPIOFactory()
dht1 = DHT22(GPIO_PIN_1, pin_factory=pin_factory)
dht2 = DHT22(GPIO_PIN_2, pin_factory=pin_factory)

# MQTT client setup
client = mqtt.Client()
client.connect(MQTT_BROKER, MQTT_PORT)

def read_dht22(pin, pin_number):
    for attempt in range(MAX_RETRIES):
        try:
            humidity, temperature = pin.humidity, pin.temperature
            if humidity is not None and temperature is not None:
                return (temperature, humidity)
            else:
                logging.error(f"Attempt {attempt + 1} failed for pin {pin_number}")
                time.sleep(RETRY_DELAY)
