import os
import time
import logging
import threading
import json
import requests
from gpiozero import PWMLED, DigitalInputDevice
from gpiozero.pins.pigpio import PiGPIOFactory
from dht import DHT22
from datetime import datetime

# Configuration
SENSOR_PIN = 4  # BCM pin for DHT22
LED_PINS = {
    'LED1': {'R': 17, 'G': 22, 'B': 27},
    'LED2': {'R': 5, 'G': 6, 'B': 13},
    'LED3': {'R': 19, 'G': 26, 'B': 16}
}
PWM_FREQUENCY = 1000
LOG_FILE = 'sensor_log.txt'
CLOUD_URL = 'http://example.com/api/data'
SAFE_TEMP_RANGE = (18, 28)
SAFE_HUMIDITY_RANGE = (30, 80)
READ_INTERVAL = 5  # seconds
UPLOAD_INTERVAL = 60  # seconds
RETRY_COUNT = 3
RETRY_DELAY = 2  # seconds

# Setup logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler(LOG_FILE),
        logging.StreamHandler()
    ]
)

# Initialize PWM LEDs
factory = PiGPIOFactory()
leds = {
    'LED1': {
        'R': PWMLED(LED_PINS['LED1']['R'], pin_factory=factory),
        'G': PWMLED(LED_PINS['LED1']['G'], pin_factory=factory),
        'B': PWMLED(LED_PINS['LED1']['B'], pin_factory=factory)
    },
    'LED2': {
        'R': PWMLED(LED_PINS['LED2']['R'], pin_factory=factory),
        'G': PWMLED(LED_PINS['LED2']['G'], pin_factory=factory),
        'B': PWMLED(LED_PINS['LED2']['B'], pin_factory=factory)
    },
    'LED3': {
        'R': PWMLED(LED_PINS['LED3']['R'], pin_factory=factory),
        'G': PWMLED(LED_PINS['LED3']['G'], pin_factory=factory),
        'B': PWMLED(LED_PINS['LED3']['B'], pin_factory=factory)
    }
}

# Initialize DHT22 sensor
dht_sensor = DHT22(SENSOR_PIN)

# Function to map temperature to RGB color
def map_temp_to_color(temp):
    if temp < SAFE_TEMP_RANGE[0]:
        return (0, 0, 1)  # Blue for cold
    elif temp > SAFE_TEMP_RANGE[1]:
        return (1, 0, 0)  # Red for hot
    else:
        # Map temperature to RGB (linear interpolation)
        red = max(0, min(1, (temp - SAFE_TEMP_RANGE[0]) / (SAFE_TEMP_RANGE[1] - SAFE_TEMP_RANGE[0])))
        green = max(0, min(1, (temp - SAFE_TEMP_RANGE[0]) / (SAFE_TEMP_RANGE[1] - SAFE_TEMP_RANGE[0])))
        blue = max(0, min(1, (temp - SAFE_TEMP_RANGE[0]) / (SAFE_TEMP_RANGE[1] - SAFE_TEMP_RANGE[0])))
        return (red, green, blue)

# Function to map humidity to brightness
def map_humid_to_brightness(humid):
    if humid < SAFE_HUMIDITY_RANGE[0]:
        return 0.2  # Low brightness for low humidity
    elif humid > SAFE_HUMIDITY_RANGE[1]:
        return 0.2  # Low brightness for high humidity
    else:
        # Map humidity to brightness (linear interpolation)
        return max(0, min(1, (humid - SAFE_HUMIDITY_RANGE[0]) / (SAFE_HUMIDITY_RANGE[1] - SAFE_HUMIDITY_RANGE[0])))

# Function to read sensor data with retries
def read_sensor_data():
    for attempt in range(RETRY_COUNT):
        try:
            dht_sensor.wait_for_valid_data()
            temp = dht_sensor.temperature
            humid = dht_sensor.humidity
            logging.info(f"Sensor data read: Temp={temp}°C, Humid={humid}%")
            return temp, humid
        except Exception as e:
            logging.error(f"Sensor read failed (Attempt {attempt + 1}/{RETRY_COUNT}): {e}")
            time.sleep(RETRY_DELAY)
    logging.error("All sensor read attempts failed")
    return None, None

# Function to update LED colors and brightness
def update_leds(temp, humid):
    color = map_temp_to_color(temp)
    brightness = map_humid_to_brightness(humid)

    for led in leds.values():
        led['R'].value = color[0] * brightness
        led['G'].value = color[1] * brightness
        led['B'].value = color[2] * brightness

# Function to check for alerts
def check_alerts(temp, humid):
    alert = None
    if temp is not None and temp < SAFE_TEMP_RANGE[0]:
        alert = "status: Temperature Alert"
    elif temp is not None and temp > SAFE_TEMP_RANGE[1]:
        alert = "status: Temperature Alert"
    elif humid is not None and humid < SAFE_HUMIDITY_RANGE[0]:
        alert = "status: Humidity Alert"
    elif humid is not None and humid > SAFE_HUMIDITY_RANGE[1]:
        alert = "status: Humidity Alert"
    return alert

# Function to upload data to cloud
def upload_data(data):
    try:
        response = requests.post(CLOUD_URL, data=json.dumps(data), headers={'Content-Type': 'application/json'})
        if response.status_code == 200:
            logging.info("Data uploaded successfully")
        else:
            logging.error(f"Failed to upload data: {response.status_code} - {response.text}")
    except Exception as e:
        logging.error(f"Upload failed: {e}")

# Main loop
def main():
    last_temp, last_humid = None, None
    last_upload_time = time.time()

    try:
        while True:
            temp, humid = read_sensor_data()
            alert = check_alerts(temp, humid)

            if temp is not None and humid is not None:
                last_temp, last_humid = temp, humid
                color = map_temp_to_color(temp)
                brightness = map_humid_to_brightness(humid)
                update_leds(temp, humid)
            else:
                if last_temp is not None and last_humid is not None:
                    temp, humid = last_temp, last_humid
                    color = map_temp_to_color(temp)
                    brightness = map_humid_to_brightness(humid)
                    update_leds(temp, humid)
                else:
                    logging.warning("No valid sensor data, using last known values")

            if time.time() - last_upload_time >= UPLOAD_INTERVAL:
                data = {
                    'timestamp': datetime.now().isoformat(),
                    'temperature': temp,
                    'humidity': humid,
                    'color': color,
                    'brightness': brightness,
                    'alert': alert
                }
                upload_thread = threading.Thread(target=upload_data, args=(data,))
                upload_thread.start()
                last_upload_time = time.time()

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    finally:
        for led in leds.values():
            for channel in led.values():
                channel.off()
        factory.close()
        logging.info("GPIO cleaned up and program exited")

if __name__ == "__main__":
    main()

