# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize I2C bus
i2c = busio.I2C(board.SCL, board.SDA)

# AHT20 sensor setup
aht20 = None

def init_sensor():
    global aht20
    try:
        # Scan I2C bus to find AHT20
        addresses = i2c.scan()
        if 0x38 not in addresses:
            logging.error("AHT20 sensor not detected on I2C bus. Retrying...")
            return False
        aht20 = adafruit_ahtx0.AHTx0(i2c)
        logging.info("AHT20 sensor initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Error initializing AHT20 sensor: {e}")
        return False

def read_sensor():
    global aht20
    try:
        temperature = aht20.temperature
        humidity = aht20.relative_humidity
        return temperature, humidity
    except RuntimeError as e:
        logging.error(f"Sensor error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected error reading sensor: {e}")
        return None, None

def validate_readings(temp, humidity):
    if temp is None or humidity is None:
        return False
    if -40 <= temp <= 85 and 0 <= humidity <= 100:
        return True
    return False

def main():
    global i2c, aht20
    try:
        if not init_sensor():
            while True:
                time.sleep(5)
                if init_sensor():
                    break
                else:
                    logging.info("Retrying sensor initialization...")
        while True:
            temp, humidity = read_sensor()
            if validate_readings(temp, humidity):
                timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                print(f"{timestamp} Temperature: {temp:.1f} C Humidity: {humidity:.1f} %")
            else:
                logging.warning("Invalid sensor readings. Retrying...")
            time.sleep(5)
    except KeyboardInterrupt:
        logging.info("Shutting down gracefully...")
        if aht20:
            aht20.deinit()
        i2c.deinit()
        sys.exit(0)
    except Exception as e:
        logging.error(f"Critical error: {e}")
        if aht20:
            aht20.deinit()
        i2c.deinit()
        sys.exit(1)

if __name__ == "__main__":
    main()

