BAUD_RATE = 9600
READ_INTERVAL = 1  # seconds
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

# Initialize serial connection
ser = None

def setup_serial():
    global ser
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        logging.info(f"Serial port {SERIAL_PORT} initialized successfully.")
    except serial.SerialException as e:
        logging.error(f"Failed to initialize serial port: {e}")
        sys.exit(1)

def read_sensor():
    global ser
    try:
        if not ser.is_open:
            ser.open()
        line = ser.readline().decode('utf-8').strip()
        if not line:
            raise ValueError("Empty line received from sensor")
        parts = line.split(',')
        if len(parts) != 2:
            raise ValueError(f"Malformed line received: {line}")
        try:
            temperature = float(parts[0])
            humidity = float(parts[1])
            return temperature, humidity
        except ValueError as e:
            logging.error(f"Invalid data format: {e}")
            return None, None
    except serial.SerialException as e:
        logging.error(f"Serial I/O error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected error during reading: {e}")
