import time
import signal
import gpiozero
from gpiozero import DigitalInputDevice
from threading import Thread

# Configuration
SENSORS = {
    17: "Sensor 1",
    27: "Sensor 2",
    22: "Sensor 3"
}
POLL_INTERVAL = 1  # seconds

# Initialize GPIO pins
def setup_sensors():
    sensors = {}
    for pin, name in SENSORS.items():
        try:
            sensor = DigitalInputDevice(pin, pull_up=True)
            sensors[name] = sensor
        except Exception as e:
            print(f"Error initializing {name} (pin {pin}): {e}")
    return sensors

# Main polling loop
def poll_sensors(sensors):
    print("Starting sensor polling...")
    while True:
        try:
            for name, sensor in sensors.items():
                if sensor.value:
                    print(f"Response for {name}")
        except Exception as e:
            print(f"Error during sensor poll: {e}")
        time.sleep(POLL_INTERVAL)

# Graceful shutdown
def signal_handler(sig, frame):
    print("\nShutting down gracefully...")
    for sensor in sensors.values():
        sensor.close()
    exit(0)

if __name__ == "__main__":
    try:
        # Setup sensors
        sensors = setup_sensors()
        if not sensors:
            print("No sensors initialized. Exiting.")
            exit(1)

        # Register signal handlers
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

        # Start polling thread
        poll_thread = Thread(target=poll_sensors, args=(sensors,))
        poll_thread.start()

        # Keep main thread alive
        poll_thread.join()

    except Exception as e:
        print(f"Critical error: {e}")
    finally:
        for sensor in sensors.values():
            sensor.close()

