            log_file.flush()
        else:
            print("No log file is currently open.")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def help_command(command=None):
    print("Available commands:")
    print("  start <filename>   - Start logging to a file and begin receiving data")
    print("  stop               - Stop receiving data and terminate the receive thread")
    print("  display            - Display the current contents of the log file")
    print("  send <data>        - Send data via the DOG device")
    print("  write <data>       - Append data directly to the log file")
    print("  exit               - Exit the program")
    if command:
        print(f"Help for '{command}':")
        if command == "start":
            print("  start <filename> - Create the file and start logging")
        elif command == "stop":
            print("  stop - Stop the receive thread and data logging")
        elif command == "display":
            print("  display - Show the current log file contents")
        elif command == "send":
            print("  send <data> - Transmit data via the DOG device")
        elif command == "write":
            print("  write <data> - Append data directly to the log file")
        elif command == "exit":
            print("  exit - Exit the program")
        else:
            print("No help available for this command.")

def main():
    global dog, log_file, log_thread, mqtt_client, mqtt_connected
    setup_gpio()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    parser = argparse.ArgumentParser(description="DOG Device CLI")
    parser.add_argument("--mqtt-broker", default="localhost", help="MQTT broker address")
    parser.add_argument("--mqtt-port", type=int, default=1883, help="MQTT broker port")
    parser.add_argument("--mqtt-topic", default="dog/data", help="MQTT topic to subscribe to")
    args = parser.parse_args()

    mqtt_broker = args.mqtt_broker
    mqtt_port = args.mqtt_port
    mqtt_topic = args.mqtt_topic

    start_mqtt()
    mqtt_client.on_message = on_message

    while True:
        try:
            command = input("dog> ").strip().split()
            if not command:
                continue
            if command[0] == "start":
                if len(command) < 2:
                    print("Usage: start <filename>")
                    continue
                filename = command[1]
                if os.path.exists(filename):
                    print(f"File '{filename}' already exists. Overwriting...")
                start_log_thread(filename)
                dog.start()
            elif command[0] == "stop":
                if dog.running:
                    dog.stop()
                    if log_thread and log_thread.is_alive():
                        log_thread.join(timeout=1)
                    print("Stopped receiving data and logging.")
                else:
                    print("No data receiving process is running.")
            elif command[0] == "display":
                display_log()
            elif command[0] == "send":
                if len(command) < 2:
                    print("Usage: send <data>")
                    continue
                data_string = ' '.join(command[1:])
                send_data(data_string)
            elif command[0] == "write":
                if len(command) < 2:
                    print("Usage: write <data>")
                    continue
                data_string = ' '.join(command[1:])
                write_data(data_string)
            elif command[0] == "help":
                if len(command) > 1:
                    help_command(command[1])
                else:
                    help_command()
            elif command[0] == "exit":
                signal_handler(None, None)
            else:
                print("Unknown command. Type 'help' for usage.")
        except KeyboardInterrupt:
            print("\nInterrupted. Exiting...")
            signal_handler(None, None)
        except Exception as e:
            print(f"Error: {e}")

if __name__ == "__main__":
    main()

