        if command == "start":
            print("  start <filename> - Create the file and start logging")
        elif command == "stop":
            print("  stop - Stop the receive thread and data logging")
        elif command == "display":
            print("  display - Show the current log file contents")
        elif command == "send":
            print("  send <data> - Transmit data via the DOG device")
        elif command == "write":
            print("  write <data> - Append data directly to the log file")
        elif command == "exit":
            print("  exit - Exit the program")
        else:
            print("No help available for this command.")

def main():
    global dog, log_file, log_thread, mqtt_client, mqtt_connected
    setup_gpio()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    parser = argparse.ArgumentParser(description="DOG Device CLI")
    parser.add_argument("--mqtt-broker", default="localhost", help="MQTT broker address")
    parser.add_argument("--mqtt-port", type=int, default=1883, help="MQTT broker port")
    parser.add_argument("--mqtt-topic", default="dog/data", help="MQTT topic to subscribe to")
    args = parser.parse_args()

    mqtt_broker = args.mqtt_broker
    mqtt_port = args.mqtt_port
    mqtt_topic = args.mqtt_topic

    start_mqtt()
    mqtt_client.on_message = on_message

    while True:
        try:
            command = input("dog> ").strip().split()
            if not command:
                continue
            if command[0] == "start":
                if len(command) < 2:
                    print("Usage: start <filename>")
                    continue
                filename = command[1]
                if os.path.exists(filename):
                    print(f"File '{filename}' already exists. Overwriting...")
                start_log_thread(filename)
                dog.start()
            elif command[0] == "stop":
