                    dog.stop()
                    if log_thread and log_thread.is_alive():
                        log_thread.join(timeout=1)
                    print("Stopped receiving data and logging.")
                else:
                    print("No data receiving process is running.")
            elif command[0] == "display":
                display_log()
            elif command[0] == "send":
                if len(command) < 2:
                    print("Usage: send <data>")
                    continue
                data_string = ' '.join(command[1:])
                send_data(data_string)
            elif command[0] == "write":
                if len(command) < 2:
                    print("Usage: write <data>")
                    continue
                data_string = ' '.join(command[1:])
                write_data(data_string)
            elif command[0] == "help":
                if len(command) > 1:
                    help_command(command[1])
                else:
                    help_command()
            elif command[0] == "exit":
                signal_handler(None, None)
            else:
                print("Unknown command. Type 'help' for usage.")
        except KeyboardInterrupt:
            print("\nInterrupted. Exiting...")
            signal_handler(None, None)
        except Exception as e:
            print(f"Error: {e}")

if __name__ == "__main__":
    main()
