import socket
import json
import threading
import time
import logging
import signal
import sys
from gpiozero import PWMLED
from threading import Lock
from datetime import datetime

# Configuration
TCP_HOST = '192.168.1.100'
TCP_PORT = 5000
LED_PINS = {
    'CPU': {
        'red': 17,
        'green': 18,
        'blue': 27
    },
    'Memory': {
        'red': 22,
        'green': 23,
        'blue': 24
    },
    'Disk I/O': {
        'red': 5,
        'green': 6,
        'blue': 13
    }
}
PWM_FREQ = 1000
LOG_FILE = 'notification_light.log'
MAX_RECONNECT_DELAY = 60  # seconds
RECONNECT_DELAY_START = 1  # seconds
DATA_RANGE = (0.0, 100.0)
COLOR_THRESHOLDS = {
    'red': (66.0, 100.0),
    'green': (33.0, 66.0),
    'blue': (0.0, 33.0)
}

# Initialize logging
logging.basicConfig(filename=LOG_FILE, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Global variables
leds = {}
lock = Lock()
connected = False
reconnect_delay = RECONNECT_DELAY_START
socket_connected = False
socket_thread = None

# Signal handlers
def signal_handler(sig, frame):
    logging.info("Received signal to exit.")
    for key in leds:
        for color in ['red', 'green', 'blue']:
            leds[key][color].off()
    if socket_connected:
        try:
            socket_connection.close()
        except:
            pass
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to map value to color intensity
def map_value_to_intensity(value, thresholds):
    if value < thresholds['blue'][1]:
        return 0.0
    elif value < thresholds['green'][1]:
        return (value - thresholds['blue'][1]) / (thresholds['green'][1] - thresholds['blue'][1])
    else:
        return (value - thresholds['green'][1]) / (thresholds['red'][1] - thresholds['green'][1])

# Function to update LED colors
def update_leds(data):
    with lock:
        for key in data:
            value = data[key]
            if not (DATA_RANGE[0] <= value <= DATA_RANGE[1]):
                logging.warning(f"Invalid data value for {key}: {value}")
                continue
            intensity = map_value_to_intensity(value, COLOR_THRESHOLDS)
            for color in ['red', 'green', 'blue']:
                if color == 'red' and value >= COLOR_THRESHOLDS['red'][0]:
                    leds[key][color].value = intensity
                elif color == 'green' and value >= COLOR_THRESHOLDS['green'][0]:
                    leds[key][color].value = intensity
                elif color == 'blue' and value <= COLOR_THRESHOLDS['blue'][1]:
                    leds[key][color].value = intensity
                else:
                    leds[key][color].value = 0.0

# Function to receive data over TCP
def receive_data():
    global socket_connected, reconnect_delay, connected
    while True:
        try:
            if not socket_connected:
                logging.info("Attempting to connect to TCP server...")
                socket_connection = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                socket_connection.settimeout(5)
                socket_connection.connect((TCP_HOST, TCP_PORT))
                socket_connected = True
                logging.info("Connected to TCP server.")
            try:
                data = socket_connection.recv(4096)
                if not data:
                    logging.warning("Connection closed by server.")
                    socket_connected = False
                    continue
