from paho.mqtt.client import MQTTMessage

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO pin definitions
LATCH_PIN = 11
CLOCK_PIN = 9
DATA_PIN = 10
MOTOR1_PWM_PIN = 13
MOTOR2_PWM_PIN = 12

# Direction bit patterns
MOTOR1_DIR_CW = 0b00000010
MOTOR1_DIR_CCW = 0b00000001
MOTOR1_DIR_STOP = 0b00000000

MOTOR2_DIR_CW = 0b00001000
MOTOR2_DIR_CCW = 0b00000100
MOTOR2_DIR_STOP = 0b00000000

# PWM frequency
PWM_FREQUENCY = 100

# Setup logging
logging.info("Initializing MotorShield with GPIO pins: LATCH=%d, CLOCK=%d, DATA=%d, MOTOR1_PWM=%d, MOTOR2_PWM=%d", LATCH_PIN, CLOCK_PIN, DATA_PIN, MOTOR1_PWM_PIN, MOTOR2_PWM_PIN)

class Motor:
    def __init__(self, pwm_pin, direction_bits, name):
        self.pwm_pin = pwm_pin
        self.direction_bits = direction_bits
        self.name = name
        self.pwm = None
        self.duty_cycle = 0
        self.running = False

    def setup(self):
        try:
            self.pwm = PWMOutputDevice(self.pwm_pin, frequency=PWM_FREQUENCY)
            logging.info("PWM setup for %s on pin %d", self.name, self.pwm_pin)
        except Exception as e:
            logging.error("Failed to setup PWM for %s: %s", self.name, e)
            raise

    def start(self, duty_cycle):
        try:
            if not self.running:
                self.pwm.value = duty_cycle / 100.0
                self.running = True
                logging.info("Started %s with duty cycle %d%%", self.name, duty_cycle)
        except Exception as e:
            logging.error("Failed to start %s: %s", self.name, e)
            raise

    def change_duty_cycle(self, duty_cycle):
        try:
            if self.running:
                self.pwm.value = duty_cycle / 100.0
                self.duty_cycle = duty_cycle
                logging.info("Changed duty cycle of %s to %d%%", self.name, duty_cycle)
        except Exception as e:
            logging.error("Failed to change duty cycle of %s: %s", self.name, e)
            raise

    def stop(self):
        try:
            if self.running:
                self.pwm.value = 0
                self.running = False
                logging.info("Stopped %s", self.name)
        except Exception as e:
            logging.error("Failed to stop %s: %s", self.name, e)
            raise

    def __del__(self):
        try:
            if self.pwm:
                self.pwm.close()
        except Exception as e:
            logging.error("Error during cleanup of %s: %s", self.name, e)

class MotorShield:
    def __init__(self, latch_pin, clock_pin, data_pin, motor1_pwm_pin, motor2_pwm_pin):
        self.latch_pin = latch_pin
        self.clock_pin = clock_pin
        self.data_pin = data_pin
        self.motor1_pwm_pin = motor1_pwm_pin
        self.motor2_pwm_pin = motor2_pwm_pin
        self.motors = []
        self.directions = []
        self.motor1 = None
        self.motor2 = None
        self.pwm1 = None
        self.pwm2 = None
        self.running = False

    def setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.latch_pin, GPIO.OUT)
            GPIO.setup(self.clock_pin, GPIO.OUT)
            GPIO.setup(self.data_pin, GPIO.OUT)
            logging.info("GPIO setup completed for shift register")
        except Exception as e:
            logging.error("Failed to setup GPIO pins: %s", e)
            raise

    def shift_out(self, data):
        try:
            GPIO.output(self.latch_pin, False)
            for bit in reversed(data):
                GPIO.output(self.clock_pin, False)
                GPIO.output(self.data_pin, bit)
                GPIO.output(self.clock_pin, True)
            GPIO.output(self.latch_pin, True)
            time.sleep(0.001)
        except Exception as e:
            logging.error("Failed to shift out data: %s", e)
            raise

    def set_directions(self, motor1_dir, motor2_dir):
        try:
            direction = (motor1_dir << 8) | motor2_dir
            self.shift_out(direction)
            logging.info("Direction bits set: 0x%x", direction)
        except Exception as e:
            logging.error("Failed to set direction bits: %s", e)
            raise

    def add_motor(self, motor):
        self.motors.append(motor)
        if motor.name == "Motor1":
            self.motor1 = motor
        elif motor.name == "Motor2":
            self.motor2 = motor

    def start(self):
        try:
            if not self.running:
                for motor in self.motors:
                    motor.start(motor.duty_cycle)
                self.running = True
                logging.info("Started all motors")
        except Exception as e:
            logging.error("Failed to start all motors: %s", e)
            raise

    def stop(self):
        try:
            if self.running:
                for motor in self.motors:
                    motor.stop()
                self.running = False
                logging.info("Stopped all motors")
        except Exception as e:
            logging.error("Failed to stop all motors: %s", e)
            raise

    def change_duty_cycle(self, motor_name, duty_cycle):
        try:
            for motor in self.motors:
                if motor.name == motor_name:
                    motor.change_duty_cycle(duty_cycle)
                    break
        except Exception as e:
            logging.error("Failed to change duty cycle for %s: %s", motor_name, e)
            raise

    def stop_all_motors(self):
        try:
            self.stop()
        except Exception as e:
            logging.error("Failed to stop all motors: %s", e)
            raise

    def __enter__(self):
        try:
            self.setup_gpio()
            self.motor1 = Motor(self.motor1_pwm_pin, MOTOR1_DIR_CW, "Motor1")
            self.motor2 = Motor(self.motor2_pwm_pin, MOTOR2_DIR_CW, "Motor2")
            self.add_motor(self.motor1)
            self.add_motor(self.motor2)
            self.motor1.setup()
            self.motor2.setup()
            self.set_directions(MOTOR1_DIR_STOP, MOTOR2_DIR_STOP)
            logging.info("MotorShield initialized")
            return self
        except Exception as e:
            logging.error("Failed to initialize MotorShield: %s", e)
            raise

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            self.stop_all_motors()
            self.motor1.__del__()
            self.motor2.__del__()
            GPIO.cleanup()
            logging.info("MotorShield cleaned up")
        except Exception as e:
            logging.error("Error during cleanup of MotorShield: %s", e)
            raise

def signal_handler(sig, frame):
    logging.info("Received signal to stop motors")
    try:
        with MotorShield(LATCH_PIN, CLOCK_PIN, DATA_PIN, MOTOR1_PWM_PIN, MOTOR2_PWM_PIN) as shield:
            shield.stop_all_motors()
    except Exception as e:
        logging.error("Error during signal handler: %s", e)
    sys.exit(0)

if __name__ == "__main__":
    import sys
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        with MotorShield(LATCH_PIN, CLOCK_PIN, DATA_PIN, MOTOR1_PWM_PIN, MOTOR2_PWM_PIN) as shield:
            # Set initial directions
            shield.set_directions(MOTOR1_DIR_CW, MOTOR2_DIR_CCW)
            # Start motors with initial duty cycles
            shield.motor1.change_duty_cycle(75)
            shield.motor2.change_duty_cycle(50)
            shield.start()
            # Wait for 5 seconds
            time.sleep(5)
            # Change Motor1 duty cycle
            shield.change_duty_cycle("Motor1", 25)
            # Wait for 1 second
            time.sleep(1)
            # Stop all motors
            shield.stop_all_motors()
    except Exception as e:
        logging.error("Main program error: %s", e)
        sys.exit(1)

