    try:
        with MotorShield(LATCH_PIN, CLOCK_PIN, DATA_PIN, MOTOR1_PWM_PIN, MOTOR2_PWM_PIN) as shield:
            shield.stop_all_motors()
    except Exception as e:
        logging.error("Error during signal handler: %s", e)
    sys.exit(0)

