import RPi.GPIO as GPIO
import time
import sys

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, driver, pin):
        self.driver = driver
        self.pin = pin
        self._initialized = False
        self._pwm = None

        try:
            if not hasattr(driver, 'setup') or not hasattr(driver, 'pwm'):
                raise MotorError("Invalid driver instance: must have setup and pwm methods")
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT)
            self._pwm = GPIO.PWM(self.pin, 1000)
            self._pwm.start(0)
            self._initialized = True
        except Exception as e:
            self._initialized = False
            self._pwm = None
            raise MotorError(f"Failed to initialize motor on pin {self.pin}: {str(e)}")

    def set_frequency(self, freq):
        if not self._initialized:
            raise MotorError("Motor not initialized or driver is invalid")
        try:
            self._pwm.ChangeFrequency(freq)
        except Exception as e:
            raise MotorError(f"Failed to set frequency to {freq}Hz: {str(e)}")

    def set_duty_cycle(self, duty):
        if not self._initialized:
            raise MotorError("Motor not initialized or driver is invalid")
        if not (0 <= duty <= 255):
            raise MotorError("Duty cycle must be between 0 and 255")
        try:
            self._pwm.ChangeDutyCycle(duty)
        except Exception as e:
            raise MotorError(f"Failed to set duty cycle to {duty}: {str(e)}")

    def stop(self):
        if self._initialized:
            self.set_duty_cycle(0)

    def close(self):
        if self._initialized:
            self.stop()
            self._pwm.stop()
            GPIO.cleanup(self.pin)
            self._initialized = False

    def __del__(self):
        try:
            self.close()
        except:
            pass

# Example usage with a mock driver (for testing purposes)
class MockDriver:
    def setup(self, pin, mode):
        return True
    def pwm(self, pin, freq, duty):
        return True

if __name__ == "__main__":
    try:
        driver = MockDriver()
        motor = Motor(driver, 18)
        print("Motor initialized")
        motor.set_frequency(1500)
        motor.set_duty_cycle(128)
        time.sleep(2)
        motor.stop()
        motor.close()
        print("Motor stopped and closed")
    except MotorError as e:
        print(f"Motor error: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(1)

