        response = self._send_modbus_request(request)
        self._parse_write_response(response)

    def close(self):
        self._close_serial_port()

    def is_connected(self) -> bool:
        return self.connected

    @contextmanager
    def open(self):
        try:
            self._open_serial_port()
            yield self
        finally:
            self.close()

