import serial
import time
import signal
import sys
import logging
from enum import Enum
from pymodbus.client.sync import ModbusSerialClient
from pymodbus.exceptions import ModbusException, ConnectionException
from pymodbus.pdu import ModbusExceptions as ModbusError
from pymodbus.exceptions import FrameError, ChecksumError, NoSuchSlaveError
from pymodbus.exceptions import ConnectionException as ModbusConnectionException

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ModbusRTUServoError(Enum):
    SUCCESS = 0
    SERIAL_PORT_NOT_AVAILABLE = 1
    SERIAL_PORT_OPEN_FAILED = 2
    MODBUS_EXCEPTION = 3
    MODBUS_TIMEOUT = 4
    MODBUS_NO_SUCH_SLAVE = 5
    MODBUS_FRAME_ERROR = 6
    MODBUS_CHECKSUM_ERROR = 7
    INVALID_INPUT = 8
    CLEANUP_FAILED = 9

class ModbusRTUServo:
    def __init__(self, port='/dev/serial0', baudrate=115200, parity='N', stopbits=1, bytesize=8, slave_id=1):
        self.port = port
        self.baudrate = baudrate
        self.parity = parity
        self.stopbits = stopbits
        self.bytesize = bytesize
        self.slave_id = slave_id
        self.client = None
        self.serial_port = None
        self._setup_serial()
        self._setup_modbus_client()

    def _setup_serial(self):
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                parity=self.parity,
                stopbits=self.stopbits,
                bytesize=self.bytesize,
                timeout=1
            )
            if not self.serial_port.is_open:
                self.serial_port.open()
            logging.info(f"Serial port {self.port} opened successfully.")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            self.serial_port = None
            raise RuntimeError("Serial port could not be opened.") from e

    def _setup_modbus_client(self):
        try:
            self.client = ModbusSerialClient(
                method='rtu',
                port=self.serial_port,
                baudrate=self.baudrate,
                parity=self.parity,
                stopbits=self.stopbits,
                bytesize=self.bytesize,
                timeout=1
            )
            self.client.connect()
            logging.info("Modbus RTU client connected successfully.")
        except (ModbusConnectionException, ConnectionException) as e:
            logging.error(f"Modbus client connection failed: {e}")
            self.client = None
            raise RuntimeError("Modbus client could not be initialized.") from e

    def _close_resources(self):
        try:
            if self.client:
                self.client.close()
                logging.info("Modbus client closed.")
            if self.serial_port and self.serial_port.is_open:
                self.serial_port.close()
                logging.info("Serial port closed.")
        except Exception as e:
            logging.error(f"Error during cleanup: {e}")
            return ModbusRTUServoError.CLEANUP_FAILED

    def _validate_slave_id(self, slave_id):
        if not isinstance(slave_id, int) or slave_id < 1 or slave_id > 247:
            return ModbusRTUServoError.INVALID_INPUT
        return ModbusRTUServoError.SUCCESS

    def _validate_register(self, register):
        if not isinstance(register, int) or register < 0 or register > 65535:
            return ModbusRTUServoError.INVALID_INPUT
        return ModbusRTUServoError.SUCCESS

    def _validate_value(self, value):
        if not isinstance(value, int) or value < 0 or value > 65535:
            return ModbusRTUServoError.INVALID_INPUT
        return ModbusRTUServoError.SUCCESS

    def _read_register(self, register):
        error = self._validate_register(register)
        if error != ModbusRTUServoError.SUCCESS:
            return error, None

        try:
            result = self.client.read_holding_registers(register, 1, unit=self.slave_id)
            if result.isError():
                return ModbusRTUServoError.MODBUS_EXCEPTION, None
            return ModbusRTUServoError.SUCCESS, result.registers[0]
        except ModbusError as e:
            logging.error(f"Modbus error reading register {register}: {e}")
            return ModbusRTUServoError.MODBUS_EXCEPTION, None
        except FrameError as e:
            logging.error(f"Modbus frame error reading register {register}: {e}")
            return ModbusRTUServoError.MODBUS_FRAME_ERROR, None
        except ChecksumError as e:
            logging.error(f"Modbus checksum error reading register {register}: {e}")
            return ModbusRTUServoError.MODBUS_CHECKSUM_ERROR, None
        except NoSuchSlaveError as e:
            logging.error(f"Modbus no such slave error reading register {register}: {e}")
            return ModbusRTUServoError.MODBUS_NO_SUCH_SLAVE, None
        except Exception as e:
            logging.error(f"Unexpected error reading register {register}: {e}")
            return ModbusRTUServoError.MODBUS_EXCEPTION, None

    def _write_register(self, register, value):
        error = self._validate_register(register)
        if error != ModbusRTUServoError.SUCCESS:
            return error

        error = self._validate_value(value)
        if error != ModbusRTUServoError.SUCCESS:
            return error

        try:
            self.client.write_register(register, value, unit=self.slave_id)
            return ModbusRTUServoError.SUCCESS
        except ModbusError as e:
            logging.error(f"Modbus error writing register {register}: {e}")
            return ModbusRTUServoError.MODBUS_EXCEPTION
        except FrameError as e:
            logging.error(f"Modbus frame error writing register {register}: {e}")
            return ModbusRTUServoError.MODBUS_FRAME_ERROR
        except ChecksumError as e:
            logging.error(f"Modbus checksum error writing register {register}: {e}")
            return ModbusRTUServoError.MODBUS_CHECKSUM_ERROR
        except NoSuchSlaveError as e:
            logging.error(f"Modbus no such slave error writing register {register}: {e}")
            return ModbusRTUServoError.MODBUS_NO_SUCH_SLAVE
        except Exception as e:
            logging.error(f"Unexpected error writing register {register}: {e}")
            return ModbusRTUServoError.MODBUS_EXCEPTION

    def move_to_position(self, position):
        register = 0  # Example register for position
        return self._write_register(register, position)

    def get_position(self):
        register = 0  # Example register for position
        error, value = self._read_register(register)
        if error == ModbusRTUServoError.SUCCESS:
            return value
        else:
            return None

    def __del__(self):
        self._close_resources()

def signal_handler(sig, frame):
    logging.info("Received signal, cleaning up...")
    sys.exit(0)

if __name__ == '__main__':
    try:
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

        servo = ModbusRTUServo()

        if not servo.serial_port or not servo.serial_port.is_open:
            logging.error("Serial port not available or failed to open.")
            sys.exit(0)

        logging.info("Starting servo demo...")
        result = servo.move_to_position(1000)
        if result != ModbusRTUServoError.SUCCESS:
            logging.error("Failed to move servo to position.")
        else:
            logging.info("Servo moved to position 1000.")

        position = servo.get_position()
        if position is not None:
            logging.info(f"Servo position: {position}")
        else:
            logging.error("Failed to read servo position.")

        logging.info("Demo complete. Shutting down...")
        servo._close_resources()
        sys.exit(0)

    except Exception as e:
        logging.error(f"Unexpected error in main: {e}")
        sys.exit(0)

