import serial
import time
import logging
import signal
import sys
import contextlib
from gpiozero import DigitalOutputDevice
from threading import Lock
from typing import Optional, List, Tuple, Any

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class GSMModule:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=2, power_pin=4):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.power_pin = power_pin
        self.serial = None
        self.power = DigitalOutputDevice(self.power_pin)
        self.lock = Lock()
        self.command_log = []
        self.response_log = []

        self._setup()

    def _setup(self):
        try:
            self.power.on()
            time.sleep(2)
            self.power.off()
            self.serial = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                timeout=self.timeout,
                write_timeout=self.timeout
            )
            if not self.serial.is_open:
                raise Exception("Failed to open serial port")
            self._verify_module()
        except Exception as e:
            self._close()
            logging.error(f"Initialization failed: {e}")
            raise

    def _verify_module(self):
        try:
            response = self._send_at("AT")
            if "OK" not in response:
                raise Exception("Module not responsive")
        except Exception as e:
            self._close()
            logging.error(f"Module verification failed: {e}")
            raise

    def _send_at(self, command: str, expected_response: Optional[str] = None) -> str:
        with self.lock:
            self.command_log.append(command)
            self.serial.write((command + "\r\n").encode())
            response = self.read_response()
            if expected_response and expected_response not in response:
                raise Exception(f"Unexpected response to {command}: {response}")
            self.response_log.append(response)
            return response

    def read_response(self, max_attempts=5, timeout=2) -> Optional[str]:
        response = ""
        for _ in range(max_attempts):
            try:
                line = self.serial.readline().decode('utf-8', errors='ignore')
                if line:
                    response += line
                    time.sleep(0.1)
            except serial.SerialException:
                break
            if len(response) > 0:
                return response.strip()
        return None

    def set_gps_reporting(self, interval_seconds=10):
        try:
            response = self._send_at(f"AT+GPSRD={interval_seconds}", "OK")
            logging.info(f"GPS reporting set to {interval_seconds} seconds")
        except Exception as e:
            logging.error(f"Failed to set GPS reporting: {e}")
            raise

    def set_message_storage(self, storage='SM'):
        try:
            response = self._send_at(f'AT+CPMS="{storage}","SM","SM"', "OK")
            logging.info(f"Message storage set to {storage}")
        except Exception as e:
            logging.error(f"Failed to set message storage: {e}")
            raise

    def send_tcp_data(self, data: str, ip: str = '192.168.100.12', port: int = 50):
        try:
            self._send_at(f"AT+CIPSTART=\"TCP\",\"{ip},{port}\"", "OK")
            time.sleep(1)
            self._send_at(f"AT+CIPSEND={len(data)}", "OK")
            self.serial.write(data.encode() + b'\x1A')
            time.sleep(1)
            self._send_at("AT+CIPCLOSE", "OK")
            logging.info("TCP data sent successfully")
        except Exception as e:
            logging.error(f"TCP data send failed: {e}")
            raise

    def send_terminator(self):
        try:
            self.serial.write(b'\x1A')
            response = self.read_response()
            if response:
                logging.info(f"Terminator response: {response}")
            else:
                logging.info("No response to terminator")
        except Exception as e:
            logging.error(f"Terminator send failed: {e}")
            raise

    def _close(self):
        if self.serial and self.serial.is_open:
            self.serial.close()
