        if current_angle == target_angle:
            return
        step = 5
        direction = 1 if target_angle > current_angle else -1
        for angle in range(current_angle, target_angle + direction, step):
            servo.set_pulse_width(int(angle / 180 * 20000))
            time.sleep(0.04)
        servo.set_pulse_width(int(target_angle / 180 * 20000))
    except (OSError, ValueError) as e:
