        signal.signal(signal.SIGTERM, signal_handler)
        print("PCA9685 ServoKit initialized successfully.")
        while True:
            try:
                command = input("Enter command (grab, release, move <channel> <angle>, exit): ").strip().lower()
                if command == "exit":
                    break
                elif command == "grab":
                    grab_object(kit)
                elif command == "release":
                    release_object(kit)
                elif command.startswith("move"):
                    parts = command.split()
                    if len(parts) != 3:
                        print("Usage: move <channel> <angle>")
                        continue
                    channel = int(parts[1])
                    angle = int(parts[2])
                    move_servo(kit, channel, angle)
                else:
                    print("Unknown command.")
            except Exception as e:
                print(f"Error: {e}")
    except Exception as e:
        print(f"Main error: {e}")
    finally:
        cleanup_kit(kit)
        print("Resources cleaned up.")

if __name__ == "__main__":
    main()

