import time
import sys
import signal
import os

class AimingController:
    def __init__(self, ld=1.0, hd=2.0):
        self.ld = ld
        self.hd = hd
        self.laser_pin = 17
        self.servo_dev = '/dev/servoblaster'
        self.servo_fd = None
        self.laser_on = False
        self.signal_received = False

        # Set up signal handling
        signal.signal(signal.SIGINT, self.signal_handler)

    def signal_handler(self, sig, frame):
        self.signal_received = True
        self.cleanup()

    def cleanup(self):
        if self.signal_received:
            print("Interrupt received, cleaning up...")
        if self.servo_fd is not None:
            try:
                os.close(self.servo_fd)
            except OSError:
                pass
        if self.laser_on:
            self.turn_laser_off()
        sys.exit(0)

    def _open_servo_device(self):
        try:
            self.servo_fd = os.open(self.servo_dev, os.O_WRONLY)
        except OSError as e:
            print(f"Error opening {self.servo_dev}: {e}")
            self.cleanup()
            sys.exit(1)

    def _write_servo(self, channel, value):
        if self.servo_fd is None:
            print("Servo device not open, cannot write.")
            return
        try:
            os.write(self.servo_fd, f"{channel}={value}\n")
        except OSError as e:
            print(f"Error writing to servo device: {e}")
            self.cleanup()
            sys.exit(1)

    def turn_laser_on(self):
        if not self.laser_on:
            try:
                os.system(f"gpio -g write {self.laser_pin} 1")
                self.laser_on = True
            except Exception as e:
                print(f"Error turning laser on: {e}")
                self.cleanup()
                sys.exit(1)

    def turn_laser_off(self):
        if self.laser_on:
            try:
                os.system(f"gpio -g write {self.laser_pin} 0")
                self.laser_on = False
            except Exception as e:
                print(f"Error turning laser off: {e}")
                self.cleanup()
                sys.exit(1)

    def aim_blocks(self, nums):
        if not nums:
            return

        self._open_servo_device()

        # Sort the indices based on the values in nums
        sorted_indices = sorted(range(len(nums)), key=lambda i: nums[i])

        for idx in sorted_indices:
            # Wait ld/2 seconds
            time.sleep(self.ld / 2)

            # Set servo positions
            hx = [133, 128, 122, 133, 128, 122, 133, 128, 122, 128]
            vy = [75, 75, 75, 72, 72, 72, 68, 68, 68, 90]
            h_pos = hx[idx]
            v_pos = vy[idx]

            self._write_servo(0, h_pos)
            self._write_servo(1, v_pos)

            # Wait ld/2 seconds
            time.sleep(self.ld / 2)

            # Turn laser on
            self.turn_laser_on()

            # Wait hd seconds
            time.sleep(self.hd)

            # Turn laser off
            self.turn_laser_off()

        self.cleanup()

import logging
import signal
import time
from gpiozero import DigitalOutputDevice
from datetime import datetime

class SolenoidController:
    def __init__(self, pin=24):
        self.pin = pin
        self.relay = None
        self.pulse_count = 0
        self.pulse_duration = 0.4
        self.pulse_delay = 1.0
        self.log_file = "solenoid_pulses.log"
        self.setup_logger()
        self.setup_gpio()

    def setup_logger(self):
        logging.basicConfig(
            filename=self.log_file,
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s'
        )

    def setup_gpio(self):
        try:
            self.relay = DigitalOutputDevice(self.pin, active_high=True, initial_value=False)
            logging.info(f"Relay initialized on GPIO {self.pin}")
        except Exception as e:
            logging.error(f"Failed to initialize relay on GPIO {self.pin}: {e}")
            raise

    def is_relay_active(self):
        return self.relay.value

    def pulse_solenoid(self):
        if self.is_relay_active():
            logging.warning("Relay is already active. Skipping pulse.")
            return

        try:
            self.relay.on()
            logging.info(f"Pulse {self.pulse_count + 1} started at {datetime.now()}")
            time.sleep(self.pulse_duration)
            self.relay.off()
            self.pulse_count += 1
            logging.info(f"Pulse {self.pulse_count} ended at {datetime.now()}")
        except Exception as e:
            logging.error(f"Error during solenoid pulse: {e}")

    def schedule_pulses(self):
        try:
            for _ in range(3):
                self.pulse_solenoid()
                time.sleep(self.pulse_delay)
        except Exception as e:
            logging.error(f"Error during pulse scheduling: {e}")
            raise

    def cleanup(self):
        if self.relay:
            self.relay.off()
            self.relay.close()
            logging.info("Relay de-energized and GPIO cleaned up.")

def signal_handler(sig, frame, controller):
    logging.info("Received signal to exit.")
    controller.cleanup()
    exit(0)

def main():
    try:
        controller = SolenoidController()
        signal.signal(signal.SIGINT, lambda sig, frame: signal_handler(sig, frame, controller))
        signal.signal(signal.SIGTERM, lambda sig, frame: signal_handler(sig, frame, controller))
        controller.schedule_pulses()
    except Exception as e:
        logging.error(f"Critical error: {e}")
    finally:
        controller.cleanup()

if __name__ == "__main__":
    main()

