from datetime import datetime, timedelta
from gpiozero import Device, I2CBus
from smbus2 import SMBus, i2c_msg
from typing import Optional, Tuple

# Constants
DS1338_I2C_ADDR = 0x68
DS1338_REG_SECONDS = 0x00
DS1338_REG_MINUTES = 0x01
DS1338_REG_HOURS = 0x02
DS1338_REG_DAY_OF_WEEK = 0x03
DS1338_REG_DAY_OF_MONTH = 0x04
DS1338_REG_MONTH = 0x05
DS1338_REG_YEAR = 0x06
DS1338_REG_CONTROL = 0x07
DS1338_CONTROL_HOUR_12_BIT = 0x10
DS1338_CONTROL_HOUR_24_BIT = 0x00
DS1338_CONTROL_STOP = 0x80
DS1338_CONTROL_SQWE = 0x20
DS1338_CONTROL_UIE = 0x10
DS1338_CONTROL_AIE = 0x08
DS1338_CONTROL_UIP = 0x04
DS1338_CONTROL_AIEP = 0x02
DS1338_CONTROL_CH = 0x01

# I2C bus configuration
I2C_BUS = 1
SDA_PIN = 2
SCL_PIN = 3

# BCD conversion functions
def bcd_to_int(value: int) -> int:
    return (value >> 4) * 10 + (value & 0x0F)

def int_to_bcd(value: int) -> int:
    return (value // 10) << 4 | (value % 10)

def validate_datetime(year: int, month: int, day: int, hour: int, minute: int, second: int) -> bool:
    try:
        datetime(year, month, day, hour, minute, second)
        return True
    except ValueError:
        return False

def read_register(bus: SMBus, address: int, reg: int) -> int:
    try:
        with i2c_msg.write(bus, [address]) as w:
            w.write(reg)
        with i2c_msg.read(bus, 1) as r:
            bus.i2c_rdwr(w, r)
        return r.buf[0]
    except (OSError, Exception) as e:
        print(f"I2C error reading register {reg}: {e}")
        return -1

def write_register(bus: SMBus, address: int, reg: int, value: int) -> bool:
    try:
        with i2c_msg.write(bus, [address, reg, value]) as w:
            bus.i2c_rdwr(w)
        return True
    except (OSError, Exception) as e:
        print(f"I2C error writing register {reg}: {e}")
        return False

def read_datetime(cen: int = 21) -> datetime:
    year = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_YEAR)
    if year == -1:
        raise RuntimeError("Failed to read year register from DS1338")
    year = bcd_to_int(year)
    year = cen * 100 + year

    month = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_MONTH)
    if month == -1:
        raise RuntimeError("Failed to read month register from DS1338")
    month = bcd_to_int(month)

    day = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_DAY_OF_MONTH)
    if day == -1:
        raise RuntimeError("Failed to read day register from DS1338")
    day = bcd_to_int(day)

    hour = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_HOURS)
    if hour == -1:
        raise RuntimeError("Failed to read hour register from DS1338")
    hour = bcd_to_int(hour & 0x3F)  # Mask bit 6 (bit 6 is 0x40)

    minute = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_MINUTES)
    if minute == -1:
        raise RuntimeError("Failed to read minute register from DS1338")
    minute = bcd_to_int(minute)

    second = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_SECONDS)
    if second == -1:
        raise RuntimeError("Failed to read second register from DS1338")
    second = bcd_to_int(second)

    return datetime(year, month, day, hour, minute, second)

def write_all(year: Optional[int] = None, month: Optional[int] = None, day: Optional[int] = None,
             hour: Optional[int] = None, minute: Optional[int] = None, second: Optional[int] = None) -> bool:
    if year is not None:
        if not (0 <= year % 100 <= 99):
            print("Invalid year value")
            return False
        year_bcd = int_to_bcd(year % 100)
    else:
        year_bcd = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_YEAR)
        if year_bcd == -1:
            return False

    if month is not None:
        if not (1 <= month <= 12):
            print("Invalid month value")
            return False
        month_bcd = int_to_bcd(month)
    else:
        month_bcd = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_MONTH)
        if month_bcd == -1:
            return False

    if day is not None:
        if not (1 <= day <= 31):
            print("Invalid day value")
            return False
        day_bcd = int_to_bcd(day)
    else:
        day_bcd = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_DAY_OF_MONTH)
        if day_bcd == -1:
            return False

    if hour is not None:
        if not (0 <= hour <= 23):
            print("Invalid hour value")
            return False
        hour_bcd = int_to_bcd(hour & 0x3F)  # Mask bit 6 (bit 6 is 0x40)
    else:
        hour_bcd = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_HOURS)
        if hour_bcd == -1:
            return False

    if minute is not None:
        if not (0 <= minute <= 59):
            print("Invalid minute value")
            return False
        minute_bcd = int_to_bcd(minute)
    else:
        minute_bcd = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_MINUTES)
        if minute_bcd == -1:
            return False

    if second is not None:
        if not (0 <= second <= 59):
            print("Invalid second value")
            return False
        second_bcd = int_to_bcd(second)
    else:
        second_bcd = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_SECONDS)
        if second_bcd == -1:
            return False

    if not write_register(bus, DS1338_I2C_ADDR, DS1338_REG_YEAR, year_bcd):
        return False
    if not write_register(bus, DS1338_I2C_ADDR, DS1338_REG_MONTH, month_bcd):
        return False
    if not write_register(bus, DS1338_I2C_ADDR, DS1338_REG_DAY_OF_MONTH, day_bcd):
        return False
    if not write_register(bus, DS1338_I2C_ADDR, DS1338_REG_HOURS, hour_bcd):
        return False
    if not write_register(bus, DS1338_I2C_ADDR, DS1338_REG_MINUTES, minute_bcd):
        return False
    if not write_register(bus, DS1338_I2C_ADDR, DS1338_REG_SECONDS, second_bcd):
        return False

    return True

def main():
    global bus
    try:
        # Initialize I2C bus
        bus = SMBus(I2C_BUS)
        # Verify DS1338 is present
        if read_register(bus, DS1338_I2C_ADDR, DS1338_REG_SECONDS) == -1:
            print("DS1338 not found on I2C bus")
            sys.exit(1)

        # Set to 24-hour format
        control = read_register(bus, DS1338_I2C_ADDR, DS1338_REG_CONTROL)
        if control == -1:
            print("Failed to read control register")
            sys.exit(1)
        if (control & DS1338_CONTROL_HOUR_12_BIT) != 0:
            if not write_register(bus, DS1338_I2C_ADDR, DS1338_REG_CONTROL, control & ~DS1338_CONTROL_HOUR_12_BIT):
                print("Failed to set 24-hour format")
                sys.exit(1)

        # Main loop
        print("DS1338 RTC interface initialized. Press Ctrl+C to exit.")
        try:
            while True:
                try:
                    dt = read_datetime()
                    print(f"Current time: {dt.strftime('%Y-%m-%d %H:%M:%S')}")
                    time.sleep(1)
                except Exception as e:
                    print(f"Error reading time: {e}")
                    time.sleep(1)
        except KeyboardInterrupt:
            print("\nExiting...")
    finally:
        # Clean up
        if 'bus' in locals():
            bus.close()
        print("I2C bus closed.")

if __name__ == "__main__":
    main()

