import serial
import time
import signal
import logging
import sys
from datetime import datetime
from contextlib import contextmanager
from typing import Optional

# Set up logging to stderr
logging.basicConfig(level=logging.WARNING, format='%(asctime)s - %(levelname)s - %(message)s')

@contextmanager
def serial_port_context(port: str, baudrate: int, timeout: float) -> Optional[serial.Serial]:
    try:
        ser = serial.Serial(port, baudrate=baudrate, timeout=timeout)
        yield ser
    except serial.SerialException as e:
        logging.error(f"Failed to initialize serial port {port}: {e}")
        sys.exit(1)
    finally:
        if 'ser' in locals():
            ser.close()

@contextmanager
def log_file_context(filename: str) -> Optional[open]:
    try:
        log_file = open(filename, 'a')
        yield log_file
    except IOError as e:
        logging.error(f"Failed to open log file {filename}: {e}")
        sys.exit(1)
    finally:
        if 'log_file' in locals():
            log_file.flush()
            log_file.close()

def signal_handler(sig, frame):
    logging.info("Received termination signal. Cleaning up...")
    sys.exit(0)

def read_co2_value(ser: serial.Serial) -> Optional[int]:
    line = ser.readline().decode('ascii', errors='replace').strip()
    if line:
        try:
            return int(line)
        except ValueError:
            logging.warning("Received non-numeric CO2 reading, skipping.")
    return None

def main():
    port = '/dev/ttyUSB0'
    baudrate = 9600
    timeout = 1.0
    log_file_name = 'co2_readings_log.txt'
    sample_interval = 5.0

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with serial_port_context(port, baudrate, timeout) as ser:
        with log_file_context(log_file_name) as log_file:
            while True:
                try:
                    co2_value = read_co2_value(ser)
                    if co2_value is not None:
                        timestamp = datetime.now().isoformat()
                        log_entry = f"{timestamp} - {co2_value} ppm\n"
                        log_file.write(log_entry)
                        print(log_entry.strip())
                    time.sleep(sample_interval)
                except Exception as e:
                    logging.error(f"Error during CO2 reading: {e}")
                    time.sleep(sample_interval)

if __name__ == "__main__":
    main()

