    try:
        ser = serial.Serial(port, baudrate=baudrate, timeout=timeout)
        yield ser
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port {port}: {e}")
        yield None
    finally:
        if 'ser' in locals() and ser.is_open:
            ser.close()

def parse_health_data(line):
    try:
        hr, spo2 = line.strip().split(',')
        hr = int(hr)
        spo2 = int(spo2)
        return hr, spo2
    except ValueError as e:
        logging.error(f"Error parsing line: {line} - {e}")
        return None, None

def log_health_data(hr, spo2):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - Heart Rate: {hr} bpm, SpO2: {spo2} %\n"
    try:
        with open("health_readings_log.txt", "a") as f:
            f.write(log_entry)
    except IOError as e:
        logging.error(f"Failed to write to log file: {e}")

def signal_handler(sig, frame):
    logging.info("Received termination signal. Exiting gracefully.")
    sys.exit(0)

def main():
    port = "/dev/ttyUSB0"
    baudrate = 9600
    timeout = 1
    delay_seconds = 5

    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    while True:
