import os
import sys
import time
import threading
import signal
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs
import json
import serial
import serial.tools.list_ports
from contextlib import contextmanager
from threading import Lock
from flask import Flask, request, jsonify
from flask_restful import Resource, Api, reqparse
from flask_cors import CORS

# Context manager for UART port
@contextmanager
def serial_port_context(port, baudrate=9600, timeout=1):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout, bytesize=8, parity='N', stopbits=1)
        yield ser
    except serial.SerialException as e:
        print(f"Failed to open serial port {port}: {e}")
        raise
    finally:
        if 'ser' in locals():
            try:
                ser.close()
            except serial.SerialException:
                pass

# Thread-safe in-memory data store
data_lock = Lock()
data_items = [
    {"id": 1, "name": "Item One", "done": False},
    {"id": 2, "name": "Item Two", "done": True}
]

def get_next_id():
    return max(item['id'] for item in data_items) + 1

def validate_item(item):
    if not isinstance(item, dict):
        return False, "Invalid item format"
    if 'name' not in item or not item['name'].strip():
        return False, "Name is required and must not be empty"
    if 'done' not in item:
        return False, "Done flag is required"
    return True, ""

def get_item_by_id(item_id):
    with data_lock:
        for item in data_items:
            if item['id'] == item_id:
                return item
        return None

def update_item(item_id, new_data):
    with data_lock:
        for i, item in enumerate(data_items):
            if item['id'] == item_id:
                data_items[i].update(new_data)
                return True
        return False

def delete_item(item_id):
    with data_lock:
        for i, item in enumerate(data_items):
            if item['id'] == item_id:
                del data_items[i]
                return True
        return False

# Flask app setup
app = Flask(__name__)
CORS(app)
api = Api(app)

# UART port
uart_port = '/dev/ttyUSB0'

# Web service endpoints
class VersionResource(Resource):
    def get(self):
        try:
            with serial_port_context(uart_port) as ser:
                ser.write(b"*IDN?\n")
                ser.flush()
                response = ser.readline()
                if not response:
                    return "", 504
                return response.decode('ascii').strip(), 200
        except serial.SerialException:
            return "Failed to open UART port", 500
        except Exception as e:
            return str(e), 502

class DataListResource(Resource):
    def get(self):
        with data_lock:
            return jsonify(data_items)

    def post(self):
        parser = reqparse.RequestParser()
        parser.add_argument('name', type=str, required=True, help="Name is required")
        parser.add_argument('done', type=bool, required=True, help="Done flag is required")
        args = parser.parse_args()
        name = args['name'].strip()
        done = args['done']
        if not name:
            return {"error": "Name cannot be empty"}, 400
        new_item = {
            "id": get_next_id(),
            "name": name,
            "done": done
        }
        with data_lock:
            data_items.append(new_item)
        return jsonify(new_item), 201

class DataItemResource(Resource):
    def get(self, item_id):
        item = get_item_by_id(item_id)
        if item:
            return jsonify(item)
        return {"error": "Item not found"}, 404

    def put(self, item_id):
        item = get_item_by_id(item_id)
        if not item:
            return {"error": "Item not found"}, 404
        parser = reqparse.RequestParser()
        parser.add_argument('name', type=str, required=True, help="Name is required")
        parser.add_argument('done', type=bool, required=True, help="Done flag is required")
        args = parser.parse_args()
        name = args['name'].strip()
        done = args['done']
        if not name:
            return {"error": "Name cannot be empty"}, 400
        updated_item = {
            "id": item_id,
            "name": name,
            "done": done
        }
        with data_lock:
            if update_item(item_id, updated_item):
                return jsonify(updated_item), 200
            return {"error": "Failed to update item"}, 500

    def delete(self, item_id):
        if delete_item(item_id):
            return "", 204
        return {"error": "Item not found"}, 404

api.add_resource(VersionResource, '/version')
api.add_resource(DataListResource, '/data')
api.add_resource(DataItemResource, '/data/<int:item_id>')

# Signal handler
def signal_handler(sig, frame):
    print("Shutting down gracefully...")
    sys.exit(0)

# Start the web server
