    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    server = HTTPServer(('0.0.0.0', 5000), BaseHTTPRequestHandler)
    print("Starting web server on 0.0.0.0:5000")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        print("Web server stopped.")

# Main function
if __name__ == "__main__":
    try:
        # Check if UART port exists
        ports = list(serial.tools.list_ports.comports())
        uart_exists = any(port.device == uart_port for port in ports)
        if not uart_exists:
            print(f"UART port {uart_port} not found. Exiting.")
            sys.exit(1)
        run_server()
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

